(() => {
    let apiResponse;
    window.shippingPage = {
        miniDetails: {},
        addressId: '',
        cartId: '',
        userOnPayment: false,
        servicePlans: '',
        wmsList: []
    };

    (async function getCartDetails() {
        //$('body').addClass('item-loader')
        const cartElement = document.getElementById('shipping-items'),
            paymentElement = document.getElementById('payment-summary-details'),
            cartid = cartElement.getAttribute('data-cart-id'),
            url = cartid.length === 0 ? '/cart/cartItems' : `/cart/cartItems/${cartid}`;
        shippingPage.cartId = cartid;
        await fetch(url)
        .then(checkStatus)
        .then((response) => {
            if (response.statusCode == 200) {
                apiResponse = response;
                paymentSummary.$mount(paymentElement)
                window.shippingPage.servicePlans = response.servicePlans || null;
                window.shippingPage.wmsList = response.wmsList || [];
                EventBus.$emit('refreshWarranties', {
                    servicePlans: window.shippingPage.servicePlans
