const orderSummary = new Vue({
    el: "#shipping-items",
    template: '#orderSummaryItems',
    data: orderSummaryData,
    methods: {
        cartItemRemovedSegment: function (cartiId) {
            cartItemRemoved(this.cartItems.filter(cartItem => {
                return cartItem.id == cartiId
            })[0], pageName)
        },
        confirmRemove: function () {
            this.confirmationDataCart.cartId = arguments[0].currentTarget.dataset.cartId
            this.confirmationDataCart.couponId = arguments[0].currentTarget.dataset.couponId
            this.confirmModalCart = true;
        },
        dispatchContinue: function (event) {
            dispatchShowPaymentMethodsEvent(event)
        },
        getCouponValue: function (value) {
            return parseInt(value) === value ? value : value.toFixed(2);
        },
        getProductPageUrl: function (name, id) {
            return `/${name.replaceAll(' ', '-').replace(/[^a-zA-Z0-9-]/g, '').toLowerCase()}/p/${id}`;
        },
        getOrderSummary: function () {
            fetch(`/checkout/selectAddress?addressId=${shippingAddressId}&cartId=${shippingPage.cartId}`)
            .then(checkStatus)
            .then((response) => {
                if (response.statusCode == 200 && response.statusCode == 200) {
                    //EventBus.$emit('refreshPromos');;
                    response.cartDTO.notServicableCartList = response.notServicableCartList;

                    apiResponse = response.cartDTO;
                    this.gotOrderSummary();
                } else {
                    showAlertMessage(false, response.message);
                    throw new Error('Error');
                }
            })
            .catch((error) => {
                fetchRequestErrorHandler(error)
            });
        },
        gotOrderSummary: function () {
            window.shippingPage.miniDetails.grandTotal = apiResponse.paymentSummary.grandTotal;
            window.shippingPage.miniDetails.deliveryCharge = apiResponse.paymentSummary.deliveryCharge
            window.shippingPage.miniDetails.totalProduct = apiResponse.totalProduct

            const isNotServiceable = !!(apiResponse.notServicableCartList && apiResponse.notServicableCartList.length > 0);
            this.disableContinue = !!(isNotServiceable || apiResponse.anyItemOutOfStock)
            this.cartItems = apiResponse.cartItems;
            this.paymentSummary = apiResponse.paymentSummary;
            this.isAnyItemOutOfStock = apiResponse.anyItemOutOfStock;
            if(apiResponse.cartItems.length > 0) {
                this.showAvailableCoupons = apiResponse.cartItems[0].preOrderId ? false : true;
            }
            this.loaded = true;
            this.orderSummaryRefreshCounter++;
            const cartItems = apiResponse.cartItems
            const today = new Date();
            const tomorrow = new Date(today);
            // tomorrow.setDate(today.getDate() + 2); // Add 2 days
            for (let index = 0; index < cartItems?.length; ++index) {

                const cartItem = cartItems[index];
                // const date = new Date(cartItems[index].buyerExpectedDeliveryDate || tomorrow)
                const dateValue = cartItems[index].buyerExpectedDeliveryDate;
                const date = dateValue ? new Date(dateValue) : null;
                if(date) {
                    const year = date.getFullYear();
                    const month = String(date.getMonth() + 1).padStart(2, '0'); // Add leading zero
                    const day = String(date.getDate()).padStart(2, '0'); // Add leading zero
                    // return `${year}-${month}-${day}`;

                    cartItems[index].buyerExpectedDeliveryDate = `${year}-${month}-${day}`;
                }
                else{
                    cartItems[index].buyerExpectedDeliveryDate = ''
                }
                if (cartItem.offerUpdated && !cartItem.outOfStock) {
                    this.offerUpdated = true;
                    break;
                }
            }
            this.cartItems = cartItems;

