 */

//
class LakshyaCartService {

	static transactional = false
	//	static transactional = 'mongo'

	def merchantGroupsService
	def catalogService
	def merchantOfferService
	def merchantServiceabilityService
	def lakshyaUtilsService
	def priceDiscoveryService
	def offerAdapterService


	def getHotDealOffer(def product, def user, def  webSite){

		def offer = catalogService.getMerchantProductWholesaleOffer(product)

		def pinCode = lakshyaUtilsService.getUserPinCode(user)

		if(offer && offer.size() > 0){
			//Filter offers on the basis of serviceability
			if(pinCode){
				offer = merchantServiceabilityService.filterServiceableOffers(offer, pinCode,user)
				offer = merchantGroupsService.updateOffers(offer, user, webSite)
				offer = offer.sort { it.offerPrice }
			}

			if(offer.size() > 0){
				return offer.get(0)
			}

		}

		return null;
	}

	def getOfferAndQuantity(def paramData, def user, def webSite){

		def offerList = []
		def qtyList   = []

		def models = paramData.models
		def offerids = paramData.offerIds
		int count = 0
		if(models){
			def quantity = paramData.quantity.tokenize(",")
			models?.tokenize(",").each{
				def product = Product.findByIdentifier(it)
				def offer = getHotDealOffer(product,user,webSite);
				if(offer){
					def data = [:]
					data.offerId = offer.id.toString()
					def  quant = Integer.parseInt(quantity[count])
					quant = offer.qty > quant ? quant: offer.qty
					data.quant = quant
					offerList << data
				}
				count++;
			}
		}else if(offerids){
			offerids.each{ ofrid ->
				def data = [:]
				data.offerId = ofrid
				def  quant = 1
				data.quant = quant
				offerList << data
			}
		}

		return offerList;
	}

	/**
	 * @param user
	 * @param webSite
	 * @param cartId
	 * @return
	 */
	def findSuggestedCartBaseCostValue(User user, def webSite, String cartId, List cartList = null){

		if(!cartList){
			cartList = UserCart.createCriteria().list(){
				eq('webSite',WebSite.get(webSite))
				eq('user',user)
				eq("cartId",cartId)
				eq("active",true)
				order("lastUpdated", "desc")
			}
		}
		cartList.each{it->
			it.offer.refresh()
			it.offer = merchantGroupsService.updateOffers(it.offer, user, webSite)
		}
		updateOfferPriceByBulkQuantity(cartList)
		def wholesaleRowTotal=0.0
		cartList.each{
			if (it.offer.wholesale){
				wholesaleRowTotal+=(lakshyaUtilsService.calculateOfferBaseCost(it.offer)) *  it.qty
			}
		}

		return wholesaleRowTotal;
	}

	/**
	 * @param user
	 * @param webSite
	 * @param cartId
	 * @return
	 */
	def findSuggestedCartValue(User user, def webSite, String cartId, List cartList = null){

		if(!cartList){
			cartList = UserCart.createCriteria().list(){
				eq('webSite',WebSite.get(webSite))
				eq('user',user)
				eq("cartId",cartId)
				eq("active",true)
				order("lastUpdated", "desc")
			}
		}
		cartList.each{it->
			it.offer.refresh()
			it.offer = merchantGroupsService.updateOffers(it.offer, user, webSite)
		}
		updateOfferPriceByBulkQuantity(cartList)

		def wholesaleRowTotal=0.0
		cartList.each{
			if (it.offer.wholesale){
				wholesaleRowTotal+=(it.offer.offerPrice) *  it.qty
			}
		}

		return wholesaleRowTotal;
	}



	def findSuggestedCartBaseValue(User user, def webSite, String cartId, List cartList = null){

				if(!cartList){
					cartList = UserCart.createCriteria().list(){
						eq('webSite',WebSite.get(webSite))
						eq('user',user)
