	def getHotDealOffer(def product, def user, def  webSite){

		def offer = catalogService.getMerchantProductWholesaleOffer(product)

		def pinCode = lakshyaUtilsService.getUserPinCode(user)

		if(offer && offer.size() > 0){
			//Filter offers on the basis of serviceability
			if(pinCode){
				offer = merchantServiceabilityService.filterServiceableOffers(offer, pinCode,user)
				offer = merchantGroupsService.updateOffers(offer, user, webSite)
				offer = offer.sort { it.offerPrice }
