	def getOfferAndQuantity(def paramData, def user, def webSite){

		def offerList = []
		def qtyList   = []

		def models = paramData.models
		def offerids = paramData.offerIds
		int count = 0
		if(models){
			def quantity = paramData.quantity.tokenize(",")
			models?.tokenize(",").each{
				def product = Product.findByIdentifier(it)
				def offer = getHotDealOffer(product,user,webSite);
				if(offer){
					def data = [:]
					data.offerId = offer.id.toString()
					def  quant = Integer.parseInt(quantity[count])
