	/**
	 * @param user
	 * @param webSite
	 * @return
	 */
	def findUserCartList(User user,def webSite,def cartId=null,def cartActive=false, def isCartPage=false,def clientId=null) {
		/*if (clientId?.contains("_")) {
			clientId= clientId.substring(0,clientId.lastIndexOf("_"))
		}*/
		if(clientId){
			def mProperties = lakshyaUtilsService.getMarketplaceProperties(clientId)
			clientId = mProperties?.marketplace
		}
		def cartList = UserCart.createCriteria().list(){
			eq('webSite',WebSite.get(webSite))
			eq('user',user)
			if(clientId?.equals(MarketplaceEnum.LTD.toString())  || clientId== null){
				or{
					isNull('marketplace')
					eq('marketplace', MarketplaceEnum.LTD.toString())
				}
			}
			else{
				eq('marketplace', clientId)
			}
			if(cartId){
				eq('cartId',cartId)
				if(cartActive){
					eq('active',true)
				}
			}else{
				isNull("cartId")
			}
			order("dateCreated", "desc")
		}
		//LIPLWEB-7016 Attach normal offer if private offer has expired
		cartList.each{ cart ->
			MerchantProductOffer offer = cart.offer;
			if(offer){
				if(offer.productLead && offer.validTill < new Date()){
					def alternateOfferMap = offerAdapterService.attachAlternateOffer(offer, user);
					if(alternateOfferMap['attached']){
						def alternateOffer = alternateOfferMap['alternateOffer']
						cart.offer = alternateOffer;
						cart.offerUpdated = true;
						cart.save(flush:true, failOnError:true)
					}
				}
			}
		}

		def cartLists = []

		cartList.each{it->
			MerchantProductOffer offer = it.offer
			if(offer){
				Product product = offer.product
				if(product){
					if(isCartPage || (offer.active && product.active)){
						offer = merchantGroupsService.updateOffers(offer, user, webSite)
						offer = catalogService.updateBulkOrderPrice(offer)
						it.offer=offer
						cartLists << it
					}
				}
			}
		}
		updateOfferPriceByBulkQuantity(cartLists)
		cartLists.each{
			if(it.offer.loyaltyDiscount && it.offer.loyaltyDiscount>0){
				it.offer.offerPrice = it.offer.offerPrice + it.offer.loyaltyDiscount
			}
		}
		return cartLists;
	}

	/**
	 * @param cartItems
	 * @return
	 */
	def updateOfferPriceByBulkQuantity(def cartItems){
		def map=[:]
		cartItems.each{cart->
			if(cart.offer.merchantDiscountConfig){
				def olist=[]
				if(map[cart.offer.merchantDiscountConfig.id.toString()]){
					olist=map[cart.offer.merchantDiscountConfig.id.toString()]
				}
				olist<<cart
				map[cart.offer.merchantDiscountConfig.id.toString()]=olist
			}else{
				updateOfferPriceByBulkQuantity(cart.offer, cart.qty)
			}
		}
		map.each{k,v->
			def qty=0;
			v.each{cart->
				qty+=cart.qty
			}
			v.each{cart->
				updateOfferPriceByBulkQuantity(cart.offer, qty)
			}
		}
	}

	/**
	 * @param offer
	 * @param qty
	 * @return
	 */
	def updateOfferPriceByBulkQuantity(def offer, def qty){
		def discount=0;
		def selQty=0
		offer.beforeBulkPrice=0
		if(offer.tierPricing){
			offer.tierPricing.each{tpricing->
				if(tpricing.minQty > selQty && tpricing.minQty <= qty){
					selQty=tpricing.minQty
					discount=tpricing.discount
				}
			}
			if(discount){
				//offer.beforeBulkPrice=offer.offerPrice
				offer.offerPrice=lakshyaUtilsService.calculateBulkDiscountPrice(offer, discount,offer.offerPrice)
			}
		}
	}

	/**
	 * @param cartId
	 * @param userId
	 * @param selectedPaymentMethod
	 * @param selectedAddressId
	 * @param wallet
	 * @return
	 */
	@Retryable
	def updateCartTempDetails(def cartId, def userId,def selectedPaymentMethod,def selectedAddressId, def wallet, def advanceAmount=null, def advancePaymentMethod=null, def skipAdvancePayment=null){
		def tempCartDetails
		if(cartId){
			tempCartDetails = TempCartDetails.findByUserIdAndCartId(userId, cartId)
		}else{
			tempCartDetails = TempCartDetails.findByUserIdAndCartIdIsNull(userId)
		}
		if(selectedPaymentMethod || selectedAddressId){
			if(!tempCartDetails){
				tempCartDetails = new TempCartDetails()
				tempCartDetails.userId = userId
			}else{
				try{
					tempCartDetails.refresh()
				}catch(Exception e){
					tempCartDetails=new TempCartDetails()
					tempCartDetails.userId = userId
				}
			}
			if(selectedPaymentMethod){
				tempCartDetails.selectedPaymentMethod = selectedPaymentMethod
			}
			if(selectedAddressId){
				tempCartDetails.selectedAddressId = selectedAddressId
			}
			if(cartId){
				tempCartDetails.cartId = cartId.toString()
			}
			if(wallet != null){
				tempCartDetails.wallet = wallet
			}
			//if(advanceAmount){
			tempCartDetails.advanceAmount = advanceAmount
			//}
			//if(advancePaymentMethod != null){
			tempCartDetails.advancePaymentMethod = advancePaymentMethod
			//}
			//if(skipAdvancePayment != null){
			tempCartDetails.skipAdvancePayment = skipAdvancePayment
			//}
			tempCartDetails.save(flush:true,deepValidate:false)
		}
		return tempCartDetails
	}

	/**
	 * @param cartId
	 * @param userId
	 * @return
	 */
	def removeCartTempDetails( def userId, def cartId){
		def tempCartDetails
		if(cartId){
			tempCartDetails = TempCartDetails.findByUserIdAndCartId(userId, cartId)
		}else{
			tempCartDetails = TempCartDetails.findByUserIdAndCartIdIsNull(userId)
		}
		if(tempCartDetails){
			//			tempCartDetails.delete()
			tempCartDetails.delete(flush:true)
		}
	}

	public def offerDetails(params, def returnInstance, def pinCode, def wst, def enableOfferQtyZero=null){
		def qty = params.qty ? Integer.valueOf(params.qty) : 1
		def productInstance = Product.get(params.productId)
		def lakshyaoffers  = []
		if(productInstance){
			def offers = MerchantProductOffer.createCriteria().list{
				eq('product',productInstance)
				//eq('merchant.active',true)
				//eq('merchant.approved',true)
				eq('active',true)
				if(!productInstance?.attributes?.stocktype){
					isNull('stockType')
				}
				eq('currency','INR') //TODO - pick this value from configuration
				//TODO - Add additional filters to pick only such offers which meet a minimum criteria for our business
				gt('regularPrice',0) // Remove any zero MRP offers
				gt('offerPrice',0) // Remove any zero price offers
				ge('validTill',new Date())
				le('validFrom',new Date())
				if(!enableOfferQtyZero){
					ge('qty',qty)
				}
				order("offerPrice", "asc")
				order("affiliateBidAbsolute","desc")
				// Get highest paying associates
				order("cplBidAbsolute","desc")
				order("cptBidAbsolute","desc")
				order("cpvBidAbsolute","desc")
				order("ppcBidAbsolute","desc")
				order("storeBidAbsolute","desc")
				order("groupBidAbsolute","desc")
				order("wholesaleBidAbsolute","desc")
			}

			offers.each{ ofr ->
				lakshyaoffers << LakshyaMerchantProductOffer.get(ofr.id)
			}
		}
		//offers=catalogService.updateEstimatedDeliveryDays(lakshyaoffers, pinCode,wst)
		lakshyaoffers
	}

