					cpv << g.render(template:"cartitem", model:[cartItemInstance:it , minimumOrderQty:minimumOrderQty, orderMultiples:orderMultiples,cartId:cartId])
				}
			} catch (Exception e){
				// Do nothing
				// Catch errors where merchant offer is no longer available in system - such offers will not be shown on cart by this try catch enclosure
				log.error("Error in shopping cart {}",e)

				try{
					//					it.delete()
				} catch (Exception ex){
					// Again do nothing
					log.error("Error in deleting item from shopping cart {}",ex)
				}

				flash.alert=message(code: 'lakshyacart.applicationerrorcart.label')

