					aff << g.render(template:"cartitem", model:[cartItemInstance:it, minimumOrderQty:minimumOrderQty, orderMultiples:orderMultiples,cartId:cartId])
				}

				if (it.offer.cpl){
					cpl << g.render(template:"cartitem", model:[cartItemInstance:it , minimumOrderQty:minimumOrderQty, orderMultiples:orderMultiples,cartId:cartId] )
				}

				if (it.offer.cpt){
					cpt << g.render(template:"cartitem", model:[cartItemInstance:it , minimumOrderQty:minimumOrderQty, orderMultiples:orderMultiples,cartId:cartId])
				}

				if (it.offer.group){
					group << g.render(template:"cartitem", model:[cartItemInstance:it , minimumOrderQty:minimumOrderQty, orderMultiples:orderMultiples,cartId:cartId])
				}

				if (it.offer.wholesale){
					wholesale << g.render(template:"wholesalecartitem", model:[storeI:storeI,cartItemInstance:it , minimumOrderQty:minimumOrderQty,maximumOrderQty:it.offer.qty, orderMultiples:orderMultiples,cartId:cartId,index:index])
					wholesaleRowTotal = userCartService.calculateWholeSaleTotal(it, wholesaleRowTotal,cartId)
					totalItems += it.qty

					if (it.offer.qty <= 0){
						anyItemOos  = true
					}
				}

				if (it.offer.store){
					if (it.offer.qty <= 0){
						anyItemOos  = true
					}
					def cashBack = rt.instantcashbackamount(affiliateBidAbsolute:it.offer.storeBidAbsolute).toDouble()

					storeRowTotal = userCartService.calculateStoreSaleTotal(it, storeRowTotal,cashBack,cartId)

					storeSavings = userCartService.calculateStoreSaving(it, storeSavings, cashBack,cartId)

					totalItems += it.qty
					store << g.render(template:"storecartitem", model:[cartItemInstance:it,storeI:storeI,anyItemOos:anyItemOos , minimumOrderQty:minimumOrderQty, orderMultiples:orderMultiples,cartId:cartId])
