	@Override
	@Secured("ROLE_USER")
	def add() {
		def user = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
		def wst = request['x-website-id'].toString()
		def usr = UserExtension.get(user.id)
		Map paramObj = request.JSON?request.JSON:params
		paramObj.wst = wst
		paramObj.usr = usr
		paramObj.modifyCartItems = lakshyaUtilsService.preorderQuantityRestriction()
		def clientId = null
		if(session["marketplace"]){
			clientId = session["clientId"]?.toString()
			paramObj.clientId = clientId
			def merchantProductOffer = MerchantProductOffer.findById(paramObj?.id)
			def productEligibility = lakshyaUtilsService.checkProductEligibility(clientId,merchantProductOffer?.product)//userCartService.checkProductEligibility(clientId,paramObj.id)
			if(productEligibility==false){
				flash.warning = message(code: 'order.restrict.marketplace.message', default: 'According to your marketplace, you are unable to buy this product.')
				chain(controller: 'lakshyaCart', action: 'index', params: params)
				return
			}
		}
		try{
			//remove applied coupons if Any
			//promotionService.removeAllAppliedUserCoupons(usr, WebSite.get(wst),"e1");

			//@ LIPLWEB-7178

			def isProductTobeAddedToCart = true;

			def alreadyAddedCartItems = userCartService.getUserCartList(user, wst, session?.getId()?.toString(), paramObj.cartId, true,clientId)

			if (alreadyAddedCartItems) {
				def offer = MerchantProductOffer.findById(paramObj.id)
				def newSku = offer.product.attributes.sellerskuid
				def newSellerName = offer.merchant.displayName

				alreadyAddedCartItems.each({
					res ->
						String existingSku = res.offer.product.attributes.sellerskuid
						String existingSellerName = res.offer.merchant.displayName
						if (offer != res.offer && existingSku == newSku && existingSellerName == newSellerName) {
							isProductTobeAddedToCart = false
							return
						}
				})
			}

			Map responseMap = [:]
			if (isProductTobeAddedToCart) {
				def isAssistWebOrder = session["marketplace"] ? session["marketplace"]?.toString() : null
				responseMap = cartService.addToCart(paramObj, request, response, session?.getId()?.toString(),null,isAssistWebOrder)

			} else {
				flash.warning = message(code: 'user.cart.restriction', default: 'Cannot add product to the cart as the same product with the same seller already exist in the cart')
				chain(controller: 'lakshyaCart', action: 'index', params: params)
				return
			}
			if(responseMap['error']){
				Map resMap = responseMap['error']
				if(resMap.msgArgs){
					flash.error = message(code:resMap.msgCode, args:resMap.msgArgs)
				}else{
					flash.error = message(code:resMap.msgCode)
				}
				chain(controller:resMap.controller, action:resMap.action, params:resMap['params'])
			}else if(responseMap['success']){
				def messages = []
				Map successMap = responseMap['success']
				if(successMap['warningMessageCode']){
					flash.warning = message(code: successMap['warningMessageCode'])
				}
				if(!params.quickCheckout){
					flash.message = message(code: successMap['messageCode0'])+" "+successMap['messageCode1']+" "+ message(code: successMap['messageCode2']) +" " +
					"<strong><span class=\"fa fa-shopping-cart\" aria-hidden=\"true\"></span> ${link(controller:'lakshyaCart',action:'index') { 'My Shopping Cart' } }</strong>"
				}
				if(successMap.msgCode && successMap.msgArgs){
					flash.message = message(code:successMap.msgCode, args:successMap.msgArgs)
				}else if(successMap.msgCode	){
					flash.message = message(code:successMap.msgCode)
				}
				if(successMap.addedOffer) {
					//					flash.addedOffer = successMap.addedOffer
					//					flash.addedOffer.qty = successMap.qty
					Map map = [:];
					map['cartId'] = params['cartId'];
					map['updateCartId'] = true;
					checkoutService.saveUserModel(usr, map);
					userCartService.updateCombos(usr, wst)
					try{
						def cartId = params['cartId'];
						def assisted = session['AssistAgent'] ? true : false
						def rsts = userCartService.getUserCartList(user, wst, null, cartId,false,clientId)
						if(cartId){
							asyncAbandonCartService.updateAbandonedCart(usr, rsts, true, assisted)
						}else{
							asyncAbandonCartService.updateAbandonedCart(usr, rsts, false, assisted)
						}
					}catch(Exception e){
						log.error ("Exception occured while updating abandoned cart details", e)
						e.printStackTrace()
					}
					if (request.xhr){
						render "Ok"
						return
					}else{
						chain(controller:successMap.controller, action:successMap.action,id:successMap['id'])
						return
					}
				}else {
					flash.error = 'Error Adding Product to cart. Please try again'
					chain(controller:'lakshyaCart', action:'index', params:params)
					return
				}
			}else {
				flash.error = 'Error Adding Product to cart. Please try again'
				chain(controller:'lakshyaCart', action:'index', params:params)
				return
			}
		}catch(Exception e){
			log.error("error : lakshyacart : message {}",e)
			flash.error = (e.getLocalizedMessage())
			chain(controller:'lakshyaCart', action:'index', params:params)
			return
		}

		print "Shopping cart is unable to determine your action.  Please contact our support team.\n"
		render "<!DOCTYPE html><html><head><script type='text/javascript'>location.reload()</script></head><html>"

		return
	}

	@Secured(['ROLE_USER'])
	def addToCart() {
		def offerId = request.JSON.offerId
		def autosuggest = request.JSON.autosuggest
		def clientId = null
		if(session["clientId"]){
			clientId = session["clientId"]?.toString()
		}
		if (autosuggest) {
			def ofr = MerchantProductOffer.get(offerId)
			def wst = request['x-website-id'].toString()
			params.productId = ofr?.product?.id?.toString()
			def userInstance = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
			def userMobile = session['userMobile'] ? session['userMobile'] : null
			if(userMobile){
				userInstance= User.findByMobile(userMobile)
			}
			def pincode = catalogService.userPinCode(userInstance)
			def offers = lakshyaCartService.getOffers(userInstance, wst, pincode, ofr.product, params)
			if (offers && offers.size() > 0) {
				ofr = offers[0]
				offerId = ofr?.id?.toString()
			}
		}

		Map paramObj = request.JSON? request.JSON : params
		if(clientId != null){
			paramObj.clientId = clientId
		}
		paramObj['id'] = offerId
		def data = addToNormalCart(paramObj)
		if(data.status =="OK"){
			data.data = null
		}
		render data as JSON
		return
	}

	def private addToNormalCart(Map paramObj) {
		def wst = request['x-website-id'].toString()
		def user = springSecurityService.currentUser
		def userMobile = session['userMobile'] ? session['userMobile'] : null
		if(userMobile){
			user= User.findByMobile(userMobile)
		}
		def usr = User.get(user.id)
		paramObj.wst = wst
		paramObj.usr = usr
		paramObj.mobile = true
		Data data = new Data()
		try {
			//paramObj.source = "APP"   Commented As per LTD-1318
			Map responseMap = cartService.addToCart(paramObj, request, response, session?.getId()?.toString())
			if (responseMap['error']) {
				Map resMap = responseMap['error']
				if (resMap.msgArgs) {
					data.errors.add([message: message(code: resMap.msgCode, args: resMap.msgArgs)])
				} else {
					data.errors.add([message: message(code: resMap.msgCode)])
				}
				data.setStatusCode(resMap.statusCode)
			} else {
				def messages = []
				Map successMap = responseMap['success']
				if (successMap['warningMessageCode']) {
					messages << message(code: successMap['warningMessageCode'])
				}
				messages << message(code: successMap['messageCode0']) + " " + successMap['messageCode1'] + " " + message(code: successMap['messageCode2'])
				data.setStatusCode(HttpStatus.OK)

				def clientId = null
				if(session["marketplace"]){
					clientId = session["clientId"]?.toString()
				}
				List cartItems = userCartService.getUserCartList(usr, wst, null, paramObj.cartId, true,clientId);

				try{
					def cartId = paramObj['cartId'];
					if(cartId){
						asyncAbandonCartService.updateAbandonedCart(usr, cartItems, true, false)
					}else{
						asyncAbandonCartService.updateAbandonedCart(usr, cartItems, false, false)
					}
				}catch(Exception e){
					log.error ("Exception occured while updating abandoned cart details", e)
					e.printStackTrace()
				}

				def isItNotReviewScreen = true
				def cartData = getCartItemList(cartItems, usr, wst, paramObj.cartId, null, null, isItNotReviewScreen)

				if (cartData) {
					data.data = cartData
					if (paramObj.cartId) {
						data.messages << message(code: 'buy.products.chosen') + " " + usr?.firstName +
								" " + message(code: 'special.basket.discount') + " " + data.data['basketDiscount']
						data.data['offerClosingTime'] = getOfferExpiringTime();
					} else {
						data.messages << message(code: 'cancel.order.online.message')
						data.messages << message(code: 'invoice.item.message')
					}
				} else {
					def msg
					data.messages << msg
				}
				def recordsMap = [:]
				recordsMap['totalCartItems'] = successMap.qty
				data.records = recordsMap
				data.messages = messages
			}
		} catch (Exception e) {
			log.error(e.getLocalizedMessage(), e)
			data.errors = ([message: e.getLocalizedMessage()])
			data.setStatusCode(HttpStatus.BAD_REQUEST)
		}
		return data

	}
	private def getOfferExpiringTime() {

		Calendar cal = Calendar.getInstance();
		cal.set(Calendar.HOUR, 23);
		cal.set(Calendar.MINUTE, 59);
		cal.set(Calendar.SECOND, 59);

		long difference = cal.getTimeInMillis() -
				Calendar.getInstance().getTimeInMillis();

		return difference
	}


