    @Secured(['ROLE_USER'])
    def deleteUserAddress(params) {

        def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null

        AddressDTO resultDTO = new AddressDTO()

        try {
            resultDTO.setUserId(usr.id.toString())
            resultDTO.setMobile(usr.mobile)
            resultDTO.setFullName(usr.fullName)

            def address = UserAddress.findByUserAndId(usr, params['id'])
            if (address) {
                address.delete(flush: true)
                resultDTO.setStatusCode(HttpStatus.OK.toString())
                resultDTO.setMessage(message(code: 'account.removedaddress.label'))
            } else {
                resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.toString())
                resultDTO.setMessage("Address not found")
            }
        } catch (Exception e) {
            log.error("error in deleting the address {}", e)
            resultDTO.setStatusCode(HttpStatus.INTERNAL_SERVER_ERROR.toString())
            resultDTO.setMessage("error in fetching the address")
        }

        render resultDTO as JSON
    }

    @Secured(['ROLE_USER'])
    def editUserAddress(params) {

        def user = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
        def responseData = [:]

        try {
            if (params.id) {
                UserAddressExtension address = UserAddressExtension.get(params.id)
                if (user?.id?.toString()?.equals(address?.user?.id?.toString())) {
                    UserAddressDTO addressDTO = new UserAddressDTO()

                    addressDTO.setId(address.id.toString())
                    addressDTO.setCompany(address.gstin?address.company:user.company?user.company:"")
                    addressDTO.setFirstName(address.firstName)
                    addressDTO.setLastName(address.lastName)
                    addressDTO.setAddressLine(address.addressLine1)
                    addressDTO.setAddressLine2(address.addressLine2)
                    addressDTO.setCity(address.city)
                    addressDTO.setState(address.state)
                    addressDTO.setPinCode(address.pinCode)
                    addressDTO.setPhone(address.phone)
                    addressDTO.setLandmark(address.landmark)
                    addressDTO.setDefaultAddress(address.defaultAddress)
                    if (address.defaultAddress) {
                        addressDTO.setSelected(true)
                    } else {
                        addressDTO.setSelected(false)
                    }

                    addressDTO.setArea(address.area)
                    addressDTO.setOtherArea(address.otherArea)
