    @Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
    def saveAddress(UserAddressExtension userAddressInstance) {
        def cartId = params['cartId']
        def webSite = request['x-website-id'] ? request['x-website-id'].toString() : null
        withForm {

            def user = springSecurityService.currentUser
            def userAddressCount = UserAddress.countByUser(user)

            def userCart = userCartService.findUserCartList(user, webSite, cartId, true)
            def anyItemOos = checkoutService.validateUserCart(userCart)
            def cartSummary = userCartService.deduceCartData(user, webSite, userCart, cartId, PromotionPlatformEnum.WEB, userAddressInstance.pinCode)
            def wholesaleRowTotal = 0
            def wholesaleGrandTotal = 0
            def surcharge = 0
            def userCoupon
            def cartItemCountInstance = userCart ? userCart.size() : 0
            def bulkDiscount = 0
            def basketDiscount = 0
            def basketCount = 0
            def firstOrderDiscount
            def comboDiscount
            def userCouponList
            def chequeBounceCharge
            def deliveryChargesText
            def tax
            if (cartSummary) {
                deliveryChargesText = cartSummary.deliveryChargesText
                wholesaleRowTotal = cartSummary.total
                wholesaleGrandTotal = cartSummary.grandTotal
                surcharge = cartSummary.deliveryCharges
                userCoupon = cartSummary.userCoupon
                bulkDiscount = cartSummary.bulkDiscount
                basketDiscount = cartSummary.basketDiscount
                basketCount = cartSummary.basketCount
                firstOrderDiscount = cartSummary.usrFirstOrderDiscount
                comboDiscount = cartSummary.comboDiscount
                userCouponList = cartSummary.userCouponList
                chequeBounceCharge = cartSummary.chequeBounceCharge
                tax = cartSummary["tax"]
            }
            def cartValidMap = lakshyaUtilsService.validateCartValue(userCart, webSite, wholesaleGrandTotal);

            userAddressInstance.setUser(user)
            userAddressInstance.webSite = WebSite.get(request['x-website-id'].toString())

            //Set default if first address
            if (userAddressCount == 0) {
                userAddressInstance.setDefaultAddress(true)
            }
            def editFirmName = lakshyaOrderService.isUserFirstOrder(user)
            def weeklyOffs = servletContext.configuration."${webSite}"."weekly_off_days"
            def weeklyOffList = weeklyOffs ? weeklyOffs.tokenize(",") : ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
            if (!userAddressInstance.validate() && userAddressInstance.hasErrors()) {
                List states = locationService.fetchStatesList()
                List districts = locationService.fetchDistrictsList(userAddressInstance.state)
                List areas = locationService.fetchAreasList(userAddressInstance.state, userAddressInstance.city)
                List countries = [CountryCodesEnum.IN.name()]

                render(model: [chequeBounceCharge : chequeBounceCharge, firstOrderDiscount: firstOrderDiscount, cartValidMap: cartValidMap,
                               basketDiscount     : basketDiscount, bulkDiscount: bulkDiscount, basketCount: basketCount, userCoupon: userCoupon, deliveryCharges: surcharge, deliveryChargesText: deliveryChargesText,
                               wholesaleRowTotal  : wholesaleRowTotal, wholesaleGrandTotal: wholesaleGrandTotal, cartItemCountInstance: cartItemCountInstance,
                               userAddressInstance: userAddressInstance, states: states, districts: districts, areas: areas, countries: countries,
                               userCouponList     : userCouponList, comboDiscount: comboDiscount, editFirmName: editFirmName, userInstance: user, weekOff: weeklyOffList, cartItemListInstance: userCart, tax: tax], view: 'editAddress')
                return
            }

            if (!locationService.validatePincode(userAddressInstance.pinCode)) {
                List states = locationService.fetchStatesList()
                List districts = locationService.fetchDistrictsList(userAddressInstance.state)
                List areas = locationService.fetchAreasList(userAddressInstance.state, userAddressInstance.city)
                List countries = [CountryCodesEnum.IN.name()]
                userAddressInstance.errors.rejectValue("pinCode", "inValid.pinCode")
                userAddressInstance.pinCode = ""
                render(model: [chequeBounceCharge : chequeBounceCharge, firstOrderDiscount: firstOrderDiscount, cartValidMap: cartValidMap,
                               basketDiscount     : basketDiscount, bulkDiscount: bulkDiscount, basketCount: basketCount, userCoupon: userCoupon, deliveryCharges: surcharge, deliveryChargesText: deliveryChargesText,
                               wholesaleRowTotal  : wholesaleRowTotal, wholesaleGrandTotal: wholesaleGrandTotal, cartItemCountInstance: cartItemCountInstance,
                               userAddressInstance: userAddressInstance, states: states, districts: districts, areas: areas, countries: countries,
                               userCouponList     : userCouponList, comboDiscount: comboDiscount, editFirmName: editFirmName, userInstance: user, weekOff: weeklyOffList, cartItemListInstance: userCart, tax: tax], view: 'editAddress')
                return
            }

            //Reset the default address
            if (userAddressInstance.defaultAddress) {
                UserAddressExtension oldDefaultAddress = UserAddressExtension.createCriteria().get {
                    eq('defaultAddress', true)
                    eq('user', user)
                    ne('_id', userAddressInstance.id)
                }
                //If a default address is already set
                if (oldDefaultAddress) {
                    oldDefaultAddress.defaultAddress = false
                    oldDefaultAddress.save(failOnError: true, flush: true)
                }
            } else {
                UserAddressExtension oldDefaultAddress = UserAddressExtension.createCriteria().get {
                    eq('defaultAddress', true)
                    eq('user', user)
                    ne('_id', userAddressInstance.id)
                }
                //If there is no default address force the current address as default
                if (!oldDefaultAddress) {
                    userAddressInstance.setDefaultAddress(true)
                }
            }

            if (userAddressInstance.tin && UserAddressExtension.findByTinAndUserNotEqual(userAddressInstance.tin, user)) {
                userAddressInstance.errors.rejectValue("tin", "tin.duplicate.error")
                List states = locationService.fetchStatesList()
                List districts = locationService.fetchDistrictsList(userAddressInstance.state)
                List areas = locationService.fetchAreasList(userAddressInstance.state, userAddressInstance.city)
                List countries = [CountryCodesEnum.IN.name()]
                render(model: [cartItemListInstance: userCart, chequeBounceCharge: chequeBounceCharge, userCouponList: userCouponList, comboDiscount: comboDiscount,
                               firstOrderDiscount  : firstOrderDiscount, cartValidMap: cartValidMap, basketDiscount: basketDiscount, bulkDiscount: bulkDiscount,
                               basketCount         : basketCount, userCoupon: userCoupon, deliveryCharges: surcharge, deliveryChargesText: deliveryChargesText, wholesaleRowTotal: wholesaleRowTotal,
                               wholesaleGrandTotal : wholesaleGrandTotal, cartItemCountInstance: cartItemCountInstance, userAddressInstance: userAddressInstance,
                               states              : states, districts: districts, comboDiscount: comboDiscount, areas: areas, countries: countries, userInstance: user, editFirmName: editFirmName, weekOff: weeklyOffList, tax: tax], view: 'editAddress')
                return
            }
            Boolean invalidGST = false;
            String errorProperty = "gstin.duplicate.error";
            if (userAddressInstance.gstin && UserAddressExtension.findByGstinAndUserNotEqual(userAddressInstance.gstin, user)) {
                invalidGST = true
            }
            if (userAddressInstance.gstin && !invalidGST) {
                /*invalidGST=masterIndiaGstinConsumerService.validateGstin(webSite,userAddressInstance.gstin)
                errorProperty="gstin.invalid.error"*/
                def gstinValidationEnabled = appConfigParamService.enableGstinValidation(webSite);
                if (gstinValidationEnabled) {
                    def response = genericGstinService.validateGstin(webSite, gstin)
                    if (response.isSuccess() == false) {
                        invalidGST = true
                        errorProperty = message(code: 'gstin.invalid.error', default: 'Invalid Gstin')
                    }
                }
            }
            if (invalidGST) {
                userAddressInstance.errors.rejectValue("gstin", errorProperty)
                List states = locationService.fetchStatesList()
                List districts = locationService.fetchDistrictsList(userAddressInstance.state)
                List areas = locationService.fetchAreasList(userAddressInstance.state, userAddressInstance.city)
                List countries = [CountryCodesEnum.IN.name()]
                userAddressInstance.gstin = ""
                render(model: [cartItemListInstance: userCart, chequeBounceCharge: chequeBounceCharge, userCouponList: userCouponList, comboDiscount: comboDiscount,
                               firstOrderDiscount  : firstOrderDiscount, cartValidMap: cartValidMap, basketDiscount: basketDiscount, bulkDiscount: bulkDiscount,
                               basketCount         : basketCount, userCoupon: userCoupon, deliveryCharges: surcharge, deliveryChargesText: deliveryChargesText, wholesaleRowTotal: wholesaleRowTotal,
                               wholesaleGrandTotal : wholesaleGrandTotal, cartItemCountInstance: cartItemCountInstance, userAddressInstance: userAddressInstance,
                               states              : states, districts: districts, comboDiscount: comboDiscount, areas: areas, countries: countries, userInstance: user, editFirmName: editFirmName, weekOff: weeklyOffList, tax: tax], view: 'editAddress')
                return
            }

            userAddressInstance.save(failOnError: true, flush: true)
            if (userAddressInstance.defaultAddress || !user.firstName || !user.company) {

                if (!user.firstName || userAddressInstance.defaultAddress) {
                    user.defaultPinCode = userAddressInstance.pinCode
                    user.firstName = userAddressInstance.firstName
                    user.lastName = userAddressInstance.lastName
                    user.pinCode = userAddressInstance.pinCode
                    user.fullName = userAddressInstance.lastName + " " + userAddressInstance.lastName ?: ""
                    locationService.setUserLocation(user)
                }
                if (!user.company) {
                    user.company = userAddressInstance.company
                }
                if (!user.gstin && userAddressInstance.gstin) {
                    user.gstin = userAddressInstance.gstin
                    user.company = userAddressInstance.company
                }
                user.save(flush: true)
                asyncCrmIntegrationService.userRegistration(user, webSite)
            } else if (!user.gstin && userAddressInstance.gstin) {
                user.gstin = userAddressInstance.gstin
                user.save(flush: true)
            }

            if (params['viewID'] == 'edit') {
                flash.message = message(code: 'account.updatedaddresssuccessfully.label')
            } else if (params['viewID'] == 'add') {
                flash.message = message(code: 'account.addedaddresssuccessfully.label')
            }

            if (cartId) {
