    @Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
    def commit(UserAddress userAddressInstance) {
        preventCache(response)
        Boolean er = false, emptyCartFlag = false, errorJsonFlag = false
        def data = new Data()
        def rsPaymentMethod = params.rsPaymentMethod
        def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
        if (params.rsPaymentMethod != null && params.rsPaymentMethod == PaymentMethodEnum.RUPIFICREDIT.toString()) {
            try {
                def resData=[:]
                def isGSTINVerified = checkoutService.getGstinStatus(usr, userAddressInstance)
                resData.isGSTINVerified = isGSTINVerified
                data.data = resData
                if (isGSTINVerified == false) {
                    data.errors << [message(code: 'lakshyacheckout.gstin.null.label', default: 'Please add gstin to the default address for placing orders.')]
                    render data as JSON
                    return
                }
            }
            catch (Exception ex){
                ex.printStackTrace()
            }
        }
        if ("NETBANKING".equals(rsPaymentMethod) || "CREDIT_DEBIT".equals(rsPaymentMethod)) {
            errorJsonFlag = true
        }
        try {
            params['addressId'] = params['id']
            params['usrId'] = usr.id
            params['baseUrl'] = utilsService.extractHostName(request)
            Map responseMap
            def marketplace = session["marketplace"] ? session["marketplace"]?.toString() : null
            if(marketplace){
                params.clientId= marketplace
            }
            def dataMap=[:]
            def assistAgent = session['AssistAgent'] ? session['AssistAgent'] : null
            def isPromotionApplicable = true
            if(assistAgent){
                isPromotionApplicable = promotionService.isPromotionAllow(assistAgent)
            }
            dataMap.isPromotionApplicable = isPromotionApplicable
            Payment.withNewSession { sess ->
                responseMap = checkoutService.createOrder(params, request, response, session, PromotionPlatformEnum.WEB,dataMap)
            }
            if (responseMap['error']) {
                Map resMap = responseMap['error']
                if (resMap.msgArgs) {
                    flash.error = message(code: resMap.msgCode, args: resMap.msgArgs)
                    data.errors << message(code: resMap.msgCode, args: resMap.msgArgs)
                } else {
                    data.errors << message(code: resMap.msgCode)
                    flash.error = message(code: resMap.msgCode)
                }
                if (errorJsonFlag) {
                    render data as JSON
                } else {
                    chain(controller: resMap.controller, action: resMap.action, params: resMap['params'])
                }

            } else if (responseMap['success']) {
                Map resMap = responseMap['success']
                emptyCartFlag = resMap['emptyCartFlag']
                Payment payment = responseMap['payment']
                if (emptyCartFlag) {
                    notify('orderCreatedPaymentPending', ['payment': payment, 'webSite': request['x-website-id'].toString()])
                }
                if (resMap.msgArgs) {
                    flash.message = message(code: resMap.msgCode, args: resMap.msgArgs)
                } else {
                    flash.message = message(code: resMap.msgCode)
                }

                /*if("payU".equals(resMap.controller)){
                   redirect(url: "/razorpay/submit.json?masterOrderId=${payment.masterOrderId}&addressId="+params['addressId'])
                    //redirect(controller:"razorpayWeb",action:"submit", params:params)

                }else{*/

                if (params.rsPaymentMethod != null && params.rsPaymentMethod == "RUPIFICREDIT") {
                    try {

                        String paymentId = payment.id.toString()
                        RupifiPayment rupifiPayment = new RupifiPayment();
                        User user = User.get(usr.id)
                        rupifiPayment.setUser(user)
                        rupifiPayment.setMasterOrderId(payment.masterOrderId)
                        rupifiPayment.setStatus("PENDING")
                        rupifiPayment.setPaymentId(paymentId)
                        rupifiPayment.save(failOnError: true, flush: true)
                    }
                    catch (Exception e) {
                        e.printStackTrace()
                    }
                }

                parseParams(resMap['params'])
                //params.walletAmount = payment.walletAmount
                forward(controller: resMap.controller, action: resMap.action, id: resMap['id'])
                // }
            } else {
                if (errorJsonFlag) {
                    data.errors << message(code: 'lakshyacheckout.technicalproblem.label')
                    render data as JSON
                } else {
                    flash.error = message(code: 'lakshyacheckout.technicalproblem.label')
                    chain(controller: 'lakshyaCheckout', action: 'shipping', id: userAddressInstance.id)
                }
            }


        } catch (Exception oc) {
            log.error("Error in creating order and payment in checkout", oc)
            if (errorJsonFlag) {
                data.errors << message(code: 'lakshyacheckout.technicalproblem.label')
                render data as JSON
            } else {
                flash.error = message(code: 'lakshyacheckout.technicalproblem.label')
                chain(controller: 'lakshyaCheckout', action: 'shipping', id: userAddressInstance.id)
            }
        }

        if (er) {
            //Handle error response
            response.status = 500
            render ""
            return
        } else {
            //Handle success response
            return
        }
        response.status = 500
        render ""
        return
    }

    def parseParams(def resmaParams) {
        def splitValue
        try {
            resmaParams.each { v ->
                String value = v
                splitValue = value.split("=")
                if (splitValue.size() > 1 && splitValue[0] && splitValue[1] && !params.containsKey(splitValue[0])) {
                    params[splitValue[0]] = splitValue[1]
                }
            }
        } catch (Exception e) {
            e.printStackTrace()
        }
    }

