        MasterCategory category = MasterCategory.findByMasterCategory("Mobiles")
        CategoryPayTMConfiguration payTM = CategoryPayTMConfiguration.findByCategoryAndPaymentMode(category, PaymentMethodEnum.CASHONDELIVERY.toString())
        Double advanceAmount = payTM ? payTM.advAmount : 0
        if (userAddressInstance != null && usr != null && (advanceAmount > 0)) {
