            Double walletAmount = params['redeem'] ? Double.parseDouble(params['redeem'].toString()) : 0
            Map rstsMap = checkoutService.findPayableAmountsForCart(usr, webSite, cartId, walletAmount, PaymentMethodEnum.CASHONDELIVERY.toString(), PromotionPlatformEnum.WEB, userAddressInstance.pinCode)
