            Map cartSummary = rstsMap['cartSummary']
            def pinCode = userAddressInstance?.pinCode
            SourcingServiceableLocation loc = SourcingServiceableLocation.findByPinCode(pinCode)
            def skipAdvancePayment = loc ? 'Y' : 'N'
            Map map = [:]
            map['skipAdvancePayment'] = skipAdvancePayment
            checkoutService.saveUserModel(userExt, map);
            def couponRedirect = [:]
            couponRedirect.controller = "lakshyaCheckout"
            couponRedirect.action = "advanceAmountCollection"
            def cartValidMap = lakshyaUtilsService.validateCartValue(rsts, webSite, cartSummary.grandTotal, params?.paymentOption);
            def defaultCurrencySymbol = servletContext.configuration."${webSite}"."default_currency_symbol"
            def storeCartCount = 0
            def storeSavings = 0
            def storeI = 0
            def storeRowTotal = 0
            def store = []
            def wholesaleCartCount = 0
            def wholesaleSavings = 0
            def wholesaleI = 0
            def wholesaleRowTotal = 0
            def wholesale = []
            Map pResult = [:]
            def totalItems = 0

            //Check serviceability of selected address
            def serviceableAddress = true
            def minimumOrderQty = 0
            def orderMultiples = 0
            def index = 0;
            def addressExt = UserAddressExtension.get(userAddressInstance.id)
            def showGstMsg = false
            if (addressExt) {
                if (null == addressExt.gstin) {
                    showGstMsg = true
                }
            }
            def anyItemOos = checkoutService.validateUserCart(rsts)

            if (rsts) {
                rsts?.each {
                    index++
                    if (springSecurityService.isLoggedIn()) {
                        it.offer = catalogService.updateEstimatedDeliveryDays(it.offer, pinCode, webSite)
                    }
                    minimumOrderQty = it.offer.minimumOrderQty ? it.offer.minimumOrderQty : it.offer.merchant.minimumOrderQty
                    orderMultiples = it.offer.multiples ? it.offer.multiples : it.offer.merchant.multiples
                    if (it.offer.store) {

                        //Check serviceability

                        if (serviceableAddress) {
                            serviceableAddress = merchantServiceabilityService.checkAvailability(it.offer.merchant, pinCode)
                        }
                        if (it.offer.qty <= 0) {
                            anyItemOos = true
                        }
                        def cashBack = rt.instantcashbackamount(affiliateBidAbsolute: it.offer.storeBidAbsolute).toDouble()
                        storeRowTotal = storeRowTotal + ((it.offer.offerPrice - cashBack) * it.qty)
                        def regularDiscount = 0
                        if (it.offer.regularPrice && it.offer.offerPrice) {
                            regularDiscount = it.offer.regularPrice - it.offer.offerPrice
                        }
                        storeSavings = storeSavings + ((it.qty * cashBack) + (regularDiscount * it.qty))

                        store << g.render(template: "storecartitem", model: [cartItemInstance: it, storeI: storeI, anyItemOos: anyItemOos,
