                    }
                    if (it.offer.wholesale) {

                        //Check serviceability
                        if (serviceableAddress) {
                            serviceableAddress = merchantServiceabilityService.checkAvailability(it.offer.merchant, pinCode)
                        }
                        def regularDiscount = 0
                        if (it.offer.regularPrice && it.offer.offerPrice) {
                            regularDiscount = it.offer.regularPrice - it.offer.offerPrice
                        }
                        wholesaleSavings = wholesaleSavings + (regularDiscount * it.qty)
                        wholesale << g.render(template: "/lakshyaCart/wholesalecartitem", model: [cartItemInstance: it, storeI: wholesaleI,
                                                                                                  anyItemOos      : anyItemOos, minimumOrderQty: minimumOrderQty, maximumOrderQty: it.offer.qty, orderMultiples: orderMultiples, cartId: cartId, actionPage: "preview",
                                                                                                  addressId       : userAddressInstance.id, index: index])
                        wholesaleRowTotal += (it.offer.offerPrice) * it.qty
                        wholesaleCartCount = wholesaleCartCount + 1
                        totalItems += it.qty
                    }
                    storeI = storeI + 1
                    wholesaleI = wholesaleI + 1
                }
                pResult['store'] = store
                pResult['wholesale'] = wholesale

            }
            def serviceableFlag = 1
            if (!serviceableAddress) {
                serviceableFlag = 0
                if (cartId) {
                    chain(controller: "checkout", action: "shipping", params: [id: cartId, serviceableFlag: serviceableFlag])
                } else {
                    chain(controller: "checkout", action: "shipping", params: [serviceableFlag: serviceableFlag])
                }
            }
            def rqAllowedMethods = checkoutService.getRqAllowedMethods(webSite, usr, pinCode)
            def isPayTMApplicable = checkoutService.isPayTMApplicable(rstsMap.advanceAmount, webSite)
            def allowedMethods = []
            rqAllowedMethods.each { methodName ->
                if (!(methodName == PaymentMethodEnum.CREDIT || methodName == PaymentMethodEnum.POSTDATEDCHEQUE || methodName == PaymentMethodEnum.CHEQUE ||
                        methodName == PaymentMethodEnum.CASHONDELIVERY || methodName == PaymentMethodEnum.NEFTRTGS)) {
                    if ((methodName == PaymentMethodEnum.PAYTM && isPayTMApplicable) || !(methodName == PaymentMethodEnum.PAYTM)) {
                        allowedMethods << methodName
                    }
                }
            }
            def payments = paymentHelperService.paymentMethods(usr, request, response, session, allowedMethods)
            def paymentEnumerations = paymentHelperService.paymentMethodEnumeration(request['x-website-id'].toString())
            def cartValidPaymentsMap = getCartValidPaymentMap(rsts, webSite, cartSummary.grandTotal)
            def discountSurchargeType = rstsMap.additionalDiscount > 0 ? 'Discount' : 'Surcharge'
            Double total = Double.parseDouble(cartSummary.grandTotal ? cartSummary.grandTotal.toString() : "0")
            def additionalAmount = rstsMap.additionalDiscount > 0 ? rstsMap.additionalDiscount : rstsMap.additionalSurcharge
            [cartValidPaymentsMap: cartValidPaymentsMap, default_currency_symbol: defaultCurrencySymbol, userCouponList: cartSummary.userCouponList,
             comboDiscount       : cartSummary.comboDiscount, paymentMethods: allowedMethods, defaultCurrency: CurrencyCodesEnum.INR,
             addressId           : userAddressInstance.id, paymentEnumeration: paymentEnumerations, user: usr, firstOrderDiscount: cartSummary.firstOrderDiscount,
             paymentOptions      : payments, couponRedirect: couponRedirect, activeProductCounts: cartSummary.basketCount,
             basketDiscount      : cartSummary.basketDiscount, cartValidMap: cartValidMap, userAddressInstance: userAddressInstance,
             serviceableAddress  : serviceableAddress, cartItemListInstance: rsts, cartItemCountInstance: rsts.size(), processedResult: pResult,
             wholesaleGrandTotal : total, wholesaleRowTotal: wholesaleRowTotal, wholesaleSavings: wholesaleSavings,
             storeRowTotal       : cartSummary.storeRowTotal, storeSavings: storeSavings, tagPoints: 0, anyItemOos: anyItemOos,
             deliveryChargesText : cartSummary.deliveryChargesText, deliveryCharges: cartSummary.deliveryCharges, grandTotal: total, userCoupon: cartSummary.userCoupon, cartId: cartId,
             bulkDiscount        : cartSummary.bulkDiscount, showGstMsg: showGstMsg, totalItems: totalItems, chequeBounceCharge: cartSummary.chequeBounceCharge,
             advanceAmount       : rstsMap.advanceAmount, walletAmount: Double.parseDouble(params?.redeem ? params?.redeem.toString() : "0"), grossTotal: rstsMap.grossTotal, discountType: discountSurchargeType,
             additionalAmount    : additionalAmount, skipAdvancePayment: skipAdvancePayment, redeem: params['redeem'], redeem1: params['redeem1'],
             paymentOption       : params['paymentOption'], surchargeDiscount: params['surchargeDiscount'], mobadvanceAmount: advanceAmount,
             billingAddress      : UserAddressExtension.get(params['billingAddress'])]
        } else {
            def requestType = params['requestType']
            if ("API".equals(requestType)) {
                def errormap = [errors: true]
                return errormap
            } else {
                chain(controller: "checkout", action: "checkPreview", params: params)
                return
            }
        }
    }

