    @Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
    def deleteAddress(params) {

        def cartId = params['cartId']
        def usr = springSecurityService.currentUser
        def address = UserAddress.findByUserAndId(usr, params['id'])

        //Set another address as default
        if (address.defaultAddress) {
            address.delete()
            def otherAddress = UserAddress.findByUser(usr)
            if (otherAddress) {
                otherAddress.setDefaultAddress(true)
                otherAddress.save(failOnError: true, flush: true)
            }
        }
        address.delete()
        flash.message = message(code: 'account.removedaddress.label')
        if (cartId) {
            chain(controller: "checkout", action: "shipping", params: [id: cartId])
        } else {
            chain(controller: "checkout", action: "shipping")
        }

        return
    }

