                    eq('documentUploaded', true)
                    ne('creditStatus', 'REJECTED')
                }

                def virtualAccount = RazorPayCustomer.findByMobile(paymentInstance.rqUser.mobile)?.virtualAccount
                checkoutService.userLedgerOnSuccess(paymentInstance.id?.toString())
                if (isAssistAgentOrder) {
                    paymentInstance.masterOrderStatus = OrderStatusEnum.PENDING;
                    paymentInstance.hasUserApprovedAssistedOrder = false;
                    paymentInstance.save(flush: true, failOnError: true);
                }
                render view: 'success', model: [razorpayVirtualAccount: virtualAccount, paymentInstance: paymentInstance, orderTrackingDetails: orderTrackingDetails,
                                                orders                : sales, promotionName: promotionName, creditApp: creditApp, isPageRefresh: isPageRefresh, preorderId: preorderId]
                return
            } else if (paymentInstance.rsStatus == PaymentStatusEnum.REJECTED) {
                // Generate event for Payment Rejected After Order Creation - May Send Email from Listeners
                notify('orderCreatedPaymentFailure', ['payment': paymentInstance, 'webSite': request['x-website-id'].toString()])
                if (isAssistAgentOrder) {
                    paymentInstance.masterOrderStatus = OrderStatusEnum.PENDING;
                    paymentInstance.hasUserApprovedAssistedOrder = false;
                    paymentInstance.save(flush: true, failOnError: true);
                }
                render view: 'rejected', model: [paymentInstance: paymentInstance, orderTrackingDetails: orderTrackingDetails, promotionName: promotionName]
                return
            } else if (paymentInstance.rsStatus == PaymentStatusEnum.HOLD || paymentInstance.rsStatus == PaymentStatusEnum.RISK ||
                    paymentInstance.rsStatus == PaymentStatusEnum.FRAUD) {
                // Generate event for Payment Rejected After Order Creation - May Send Email from Listeners
                notify('orderCreatedPaymentHeld', ['payment': paymentInstance, 'webSite': request['x-website-id'].toString()])
                if (isAssistAgentOrder) {
                    paymentInstance.masterOrderStatus = OrderStatusEnum.PENDING;
                    paymentInstance.hasUserApprovedAssistedOrder = false;
                    paymentInstance.save(flush: true, failOnError: true);
                }
                render view: 'risk', model: [paymentInstance: paymentInstance, orderTrackingDetails: orderTrackingDetails]
                return
            } else if (paymentInstance.rsStatus == PaymentStatusEnum.PENDING) {
                // Generate event for Payment Rejected After Order Creation - May Send Email from Listeners
                notify('orderCreatedPaymentPending', ['payment': paymentInstance, 'webSite': request['x-website-id'].toString()])
                if (isAssistAgentOrder) {
                    paymentInstance.masterOrderStatus = OrderStatusEnum.PENDING;
                    paymentInstance.hasUserApprovedAssistedOrder = false;
                    paymentInstance.save(flush: true, failOnError: true);
                }
                render view: 'pending', model: [paymentInstance: paymentInstance, orderTrackingDetails: orderTrackingDetails]
                return
            } else if (paymentInstance.rsStatus == PaymentStatusEnum.PAYUHOLD) {
                if (isAssistAgentOrder) {
                    paymentInstance.masterOrderStatus = OrderStatusEnum.PENDING;
                    paymentInstance.hasUserApprovedAssistedOrder = false;
                    paymentInstance.save(flush: true, failOnError: true);
                }
                render view: 'success', model: [paymentInstance: paymentInstance, orderTrackingDetails: orderTrackingDetails, isPageRefresh: isPageRefresh, preorderId: preorderId]
                return
            }
            if (isAssistAgentOrder) {
                paymentInstance.masterOrderStatus = OrderStatusEnum.PENDING;
                paymentInstance.hasUserApprovedAssistedOrder = false;
                paymentInstance.save(flush: true, failOnError: true);
            }
        }

        // flash.error = message(code: 'lakshyacheckout.placefreshorder.label')
        chain(controller: 'account', action: 'orders')

    }

