    private def getBankDetails(def paymentMethodType = null) {
        def bankDetails = [:]
        bankDetails.accountNumber = message(code: 'bankdetails.accountnumber')
        bankDetails.beneficiaryName = message(code: 'bankdetails.beneficiaryname')
        bankDetails.bankName = message(code: 'bankdetails.bankname')
        bankDetails.branchName = message(code: 'bankdetails.branchname')
        bankDetails.address = message(code: 'bankdetails.address')
        bankDetails.ifsccode = message(code: 'bankdetails.ifsccode')
        if ("CHEQUE".equals(paymentMethodType)) {
            bankDetails.message = message(code: 'cheque.bankdetails.message')
