            def dataMap = [:]
            dataMap['user'] = usr
            dataMap['website'] = wst
            dataMap['chequeAmount'] = chqamnt
            dataMap['isWalletSelected'] = isWalletSelected
            dataMap['isElectricalOrder'] = isElectricalOrder
            dataMap['paymentType'] = paymentType

            paymentMap = chequePaymentService.chequePaymentMethodConditions(paymentMap, dataMap);

            /*if(lakshyaOrderService.isChequeApplicableOnOrderAmount(usr, wst,chqamnt) && isWalletSelected){
                paymentMap["refresh"] = true
            }

            boolean ischkApplicable = lakshyaOrderService.isChequeApplicable(wst,usr,chqamnt,isElectricalOrder)
            def blocked = checkoutService.isChequeCodBlocked(usr, wst)
            Boolean isChequeBlocked = blocked['cheque']
            def chqAvailable = lakshyaOrderService.reasonForChequeUnavailabilityV2(wst,usr,chqamnt,isElectricalOrder,paymentType)
            paymentMap["cdcDocumentUploaded"] = chqAvailable?.cdcDocumentUploaded
            paymentMap["userBalance"] = chqAvailable?.availableLimit
            if(!ischkApplicable){
                if(!isChequeBlocked){
                    paymentMap["active"] = ischkApplicable
                    paymentMap["error"] = chqAvailable['Reason']
                }else if(!chqAvailable['Allowed']){
                    paymentMap["active"] = chqAvailable['Allowed']
                    paymentMap["error"] = chqAvailable['Reason']
                }
            }else{
                paymentMap["isKYCApproved"] = chqAvailable?.isKYCApproved
            }
            def pdcDays = usr.chequePDCDays?usr.chequePDCDays:0
            def cdcLimit = usr.cdcLimit?usr.cdcLimit:0
            paymentMap["isKYCRejected"] = usr.isKYCRejected
            if(usr.isKYCApproved || pdcDays > 0 || cdcLimit > 0 ){
                paymentMap["isKYCApproved"] = true
            }else{
                paymentMap["isKYCApproved"] = false
            }*/


            //println "usr.isKYCApproved :: ${usr.isKYCApproved}"
        }

        if ("CREDIT".equals(paymentType) || "CREDIT14".equals(paymentType) || "CREDIT28".equals(paymentType)) {
            def userBalance = lakshyaNBFCService.userBalance(usr, wst, null, false, isElectricalOrder)
            def balance = lakshyaNBFCService.userBalance(usr, wst, null, true, isElectricalOrder)
            //userBalance = balance.balanceAmount?balance.balanceAmount:0
            def discountSurchargeValue =0.0
            if(paymentInfo)
             discountSurchargeValue = lakshyaOrderService.getAdditionalDiscountSurchargeValue(paymentInfoAmnt, paymentType, usr, cartId, wst)
            def amnt = paymentInfo ? new Double(discountSurchargeValue.toString()).round(2) : new Double(amount.toString()).round(2)

            if (walletAmount && isWalletSelected) {
                amnt = amnt - walletAmount
            }

            if (new Double(userBalance) <= amnt && isWalletSelected) {
                paymentMap["refresh"] = true
            }

            //def existingApplications = CreditApplication.findByUserAndDocumentUploadedAndStatusAndCreditStatus(usr,true,CreditApplicationEnum.APPROVED,CreditApplicationEnum.APPROVED)
            def existingApplicationsList = CreditApplication.findAllByUserAndDocumentUploaded(usr, true)
            def existingApplications //= CreditApplication.findByUserAndDocumentUploaded(usr,true)
            existingApplicationsList.each { app ->
                if (CreditApplicationEnum.APPROVED.name().equals(app.status)) {
                    existingApplications = app
                }
            }

            if (!existingApplications && existingApplicationsList && existingApplicationsList.size() > 0) {
                existingApplications = existingApplicationsList.get(0)
            }

            def payment = Payment.findByRqUserAndMasterOrderStatusAndRsPaymentMethodUsed(usr, OrderStatusEnum.CREDIT_PENDING, PaymentMethodEnum.CREDIT)

            if (payment) {
                paymentMap["active"] = false
            }
            if (existingApplications) {
                paymentMap["isKYCDocumentsUploaded"] = true
                if (CreditApplicationEnum.APPROVED.name()?.equals(existingApplications.status) && CreditApplicationEnum.APPROVED.name()?.equals(existingApplications.creditStatus)) {
                    paymentMap["isKYCApproved"] = true
                } else {
                    paymentMap["isKYCApproved"] = false
                }
                if (CreditApplicationEnum.REJECTED.name()?.equals(existingApplications.status)) {
                    paymentMap["isKYCRejected"] = true
                } else {
                    paymentMap["isKYCRejected"] = false
                }
            } else {
