    def modifyWalletData(def walletBalance, def data, def minWalletBalanceToMaintain) {
        if (minWalletBalanceToMaintain) {
            if (walletBalance) {
                if (walletBalance <= minWalletBalanceToMaintain) {
                    if (walletBalance < minWalletBalanceToMaintain) {
                        data.data.canApplyWallet = false;
                        data.data.walletMessage = "Sorry, your wallet doesn't have sufficient balance of Rs.${minWalletBalanceToMaintain} required to confirm this order. Please select a different payment option or recharge your wallet to continue.";
                    } else if (walletBalance == minWalletBalanceToMaintain) {
                        data.data.hideWallet = true;
                    }
                } else {
                    data.data.reducedWalletBalance = (walletBalance - minWalletBalanceToMaintain);
                    data.data.minWalletBalanceToMaintain = minWalletBalanceToMaintain;
                }
            } else {
                data.data.canApplyWallet = false;
                data.data.walletMessage = "Sorry, your wallet doesn't have sufficient balance of Rs.${minWalletBalanceToMaintain} required to confirm this order. Please select a different payment option or recharge your wallet to continue.";
            }
        }
    }

