								successMap['action'] = 'submit'
							}
						}else {
							successMap['action'] = 'zeroCodProcess'
							paramMap['cod'] = true
							successMap['params'] = paramMap
						}
					}else if(rsPaymentMethod.equals(PaymentMethodEnum.CHEQUE.toString()) ||
					rsPaymentMethod.equals(PaymentMethodEnum.POSTDATEDCHEQUE.toString())){
						successMap['action'] = 'processCheque'
					}else if(rsPaymentMethod.equals(PaymentMethodEnum.NEFTRTGS.toString())){
						successMap['action'] = 'neftRTGSProcess'
					}else if(rsPaymentMethod.equals(PaymentMethodEnum.WALLET.toString())){
						successMap['action'] = 'fullWalletRedemption'
					}else if(rsPaymentMethod.equals(PaymentMethodEnum.PAYLATER.toString())){
						if(payment.isAdvanceAmountApplicable) {
							if(paramObj['advancePaymentMethod'] == null ) {
								if(userExt.skipAdvancePayment == 'Y') {
									successMap['action'] = 'zeroCodProcess'
									paramMap['cod'] = true
								}else {
									errorMap['msgCode'] = 'lakshyacheckout.advanceAmountPaymentMethod.selection.label'
									responseMap['error'] = errorMap
									return responseMap
								}
							}else {
								def payments = paymentHelperService.paymentOptions(payment, request, response, session)
								String paymentModesFinal = null
								payments.each{
									if(it['rqMethod'].toString().equals(paramObj['advancePaymentMethod'].toString())){
										paymentModesFinal = it['actionUrl']
									}
								}
								successMap['controller'] = (paymentModesFinal ? paymentModesFinal.split("${httpCode}://${baseUrl}/")[1].split("/")[0]: 'payU')
								successMap['action'] = 'submit'
							}
						}else {
							successMap['action'] = 'zeroCodProcess'
							paramMap['cod'] = true
							successMap['params'] = paramMap
						}
					}else {
						Map payments = paymentHelperService.paymentMethods(payment.rqUser, request, response, session, null, isElectricalOrder)
						String paymentModesFinal = null
						payments.each{rqMethod, v->
							if(rqMethod.toString().equals(rsPaymentMethod.toString())){
								paymentModesFinal = v['actionUrl']
							}
						}
						successMap['controller'] = (paymentModesFinal ? paymentModesFinal.split("${httpCode}://${baseUrl}/")[1].split("/")[0]: 'payU')
						successMap['action'] = 'submit'
					}
				}

				responseMap['payment'] = payment
				responseMap['paymentMap'] = paymentMap
				responseMap['success'] = successMap
				try{
					if(walletAmt) {
						asyncLakshyaUserActivityUpdateService.updateUserWalletAmount(userExt, wst,["marketplace":marketplace])
					}
					if(payment.rsPaymentMethodUsed.toString().equals(PaymentMethodEnum.RUPIFICREDIT.toString())){
