						asyncLakshyaUserActivityUpdateService.updateUsercreditdetails(userExt,wst,request)
					}

					asyncLakshyaUserActivityUpdateService.updateLastOrder(userExt)
				}
				catch (Exception ex){
					ex.printStackTrace()
				}
			}
		}catch(TransactionSystemException e){
			log.error "TransactionSystemException {}"+e
			errorMap['msgCode'] = 'lakshyacheckout.technicalproblem.label'
			errorMap['action'] = 'shipping'
			errorMap['statusCode'] = (HttpStatus.BAD_REQUEST)
