	def reviseQuantity(LakshyaMerchantProductOffer o,qty){
		try {
			o.refresh();
			//synchronized(o.id){
			// LakshyaMerchantProductOffer.withNewTransaction{
			def newQty = 0
			if(o.manageInventory==null || o.manageInventory){
				if(o?.productLead) {
					newQty = o?.inventoryQty-qty
				} else {
					newQty = o.qty-qty
				}
				def existingQtyInCart = o.qtyInCart
				def newqtyInCart = existingQtyInCart +  qty
				if(o?.productLead) {
					o.setInventoryQty(newQty)
					o.setQty(newQty)
				} else {
					o.setQty(newQty)
				}
				o.setQtyInCart(newqtyInCart)
				if(o.actualQty!=null){
					if(o.actualQty>=qty){
						o.setActualQty(o.actualQty-qty)
					}else{
						def remainQty=qty-o.actualQty
						o.setActualQty(0)
						if(remainQty && o.virtualQty){
							int q=o.virtualQty-remainQty
							o.setVirtualQty(q>0?q:0)
						}
					}
				}
				o.qtyDiscountType = o.qtyDiscountType  ? o.qtyDiscountType : DiscountTypeEnum.ABSOLUTE
				lakshyaUtilsService.offerEventLog(o, "reviseQuantity");
				o.save(flush:true, deepValidate:false);
				lakshyaUtilsService.offerEventLog(o, "reviseQuantity");
			}
			//}
			//}
		} catch (Exception e){
			log.error ("Error in Revise Offer Quantity {}",e)
			throw e
		}
		return o
	}

	def findCreditNotesMerchants(User user, String webSite,def  rsts){
		def date = new Date()
		Calendar cal = Calendar.getInstance()
		cal.setTime(date)
		WebSite wst = WebSite.findById(webSite)
		def wallets = Wallet.createCriteria().list {
			eq('webSite',wst)
			eq('active',true)
			eq('user', user)
			le('expires',lakshyaUtilsService.getEndDate(cal))
		}

		Set merchants = [] as LinkedHashSet
		wallets.each{wallet->
			Merchant merchant = wallet.merchant
			if(merchant){
				merchants << merchant.id.toString()
			}
		}

		Set creditNotesIds = [] as LinkedHashSet
		def carts = []
		merchants.each{m->
			rsts.each{cart->
				MerchantProductOffer offer = cart.offer
				Merchant merch = offer.merchant
				if(merch.id.toString().equals(m)){
					if(!creditNotesIds.contains(cart.id)){
						creditNotesIds << cart.id
						carts << cart
					}
				}
			}
		}

		rsts.each{
			if(!creditNotesIds.contains(it.id)){
				creditNotesIds << it.id
				carts << it
			}
		}

		List<?> list = new ArrayList<?>(carts)
		list
	}


