	def findDiscountShare(Double discountAmount,def userCartList,def cartLevelAmount, def creditNoteMap = [:]){
		Double total = 0.0
		userCartList.each{userCartItem ->
			def creditNoteAmount = creditNoteMap[userCartItem?.id?.toString()] ? creditNoteMap[userCartItem?.id?.toString()] : 0
			def cartCreditNoteAmount = creditNoteMap[userCartItem?.id] ? creditNoteMap[userCartItem?.id] : 0
			Double cartAmount = cartLevelAmount[userCartItem?.id?.toString()]
			if(cartAmount){
				total += (cartAmount - creditNoteAmount - cartCreditNoteAmount)
			}
		}

		//deduce cart share
		def cartLevelShare = [:]
		def lastCartItemId = null;
		Double lastCartShare = 0;
		Double totalShare = 0;
		List cartLevelIds = []
		userCartList.each{userCartItem ->
			Double cartAmount = cartLevelAmount[userCartItem?.id?.toString()] ? Double.parseDouble(cartLevelAmount[userCartItem?.id?.toString()].toString()) : 0
			def creditNoteAmount = creditNoteMap[userCartItem?.id?.toString()] ? creditNoteMap[userCartItem?.id?.toString()] : 0
			def cartCreditNoteAmount = creditNoteMap[userCartItem?.id] ? creditNoteMap[userCartItem?.id] : 0
			cartAmount = (cartAmount - creditNoteAmount - cartCreditNoteAmount)
			if(cartAmount > 0){
				Double cartShare = (cartAmount >= total) ? discountAmount : (cartAmount/total)*discountAmount;
				if(cartShare!=null)
				cartShare = Math.max(cartShare.round(0),0)
				cartLevelShare[userCartItem?.id?.toString()] = cartShare
				lastCartItemId = userCartItem?.id?.toString();
				lastCartShare = cartShare
				totalShare += cartShare;
			}else{
				cartLevelIds << userCartItem?.id?.toString()
			}
		}

		//any value due to rounding
		Double remainingShare = discountAmount ? discountAmount - totalShare : 0
		if(cartLevelIds && cartLevelIds.size() > 0){
			Double commonShare = remainingShare / cartLevelIds.size()
			cartLevelIds.each{cartLevelId ->
				Double share = cartLevelShare[cartLevelId] ? Double.parseDouble(cartLevelShare[cartLevelId].toString()) : 0
				cartLevelShare[cartLevelId] =  (remainingShare+commonShare).round(0)
			}
		}else{
