	 * Method to send clever tap notification On shared order link click
	 * @param orderTrackingDetails
	 * @return
	 */
	def sendDataToCleverTap(def orderTrackingDetails, def url, def accountId, def passcode,def source){
		try{
			def jsonInput = getChargedRequestData(orderTrackingDetails,source)
			def http = new HTTPBuilder(url)

			http.request(Method.POST, ContentType.JSON ) {
				body = jsonInput.toString();
				headers.'content-type' = 'application/json'
				headers.'X-CleverTap-Account-Id' = accountId
				headers.'X-CleverTap-Passcode' = passcode

				response.success = { resp->
					log.debug "POST response status: ${resp.status}"
				}
				response.failure = { resp ->
					log.error "Unexpected error: ${resp.status}"
				}
			}

		}catch(Exception e){
			log.error("error in sending the data to clever tap {}" + e);
		}
	}

