	def isChequeCodBlocked(User userExt, def webSite){
		def globalCODLimit = new Double("0"), globalChequeLimit = new Double("0")
		def chequeOrderAmount = servletContext.configuration."${webSite}"."cheque_order_limit"
		def limitMap=lakshyaUtilsService.userGroupChequeLimitConfiguration(webSite)
		def codLimitMap=lakshyaUtilsService.userGroupCODLimitConfiguration(webSite)
		if(codLimitMap && userExt.groupName && codLimitMap[userExt.groupName]!=null){
			globalCODLimit = codLimitMap[userExt.groupName] ? new Double(codLimitMap[userExt.groupName].toString()) : new Double("0")
		}
		globalChequeLimit = new Double(chequeOrderAmount.toString())
		if(globalChequeLimit == 0 && limitMap && userExt.groupName && limitMap[userExt.groupName]!=null){
			globalChequeLimit = limitMap[userExt.groupName] ? new Double(limitMap[userExt.groupName].toString()) : new Double("0")
		}
		def	isCodBlocked = (userExt.codBlocked || (userExt.codAmountLimit != null && userExt.codAmountLimit == 0) || (userExt.codAmountLimit == null && globalCODLimit == 0))
		def isChequeBlocked = (userExt.chequeBlocked || (userExt.actualChequeLimit != null && userExt.actualChequeLimit == 0) || (userExt.actualChequeLimit == null && globalChequeLimit == 0))
		def blocked = [:]
		blocked['cod'] = isCodBlocked
		blocked['cheque'] = isChequeBlocked
		blocked
	}

