	private def updateDeltaOffer(LakshyaMerchantProductOffer offer, User user,  String webSite) {
		if(!offer.productLead && !offer.biddingData){
			Double deltaAmount = 0
			DeltaSignEnum sign = DeltaSignEnum.PLUS
			DeltaTypeEnum type = DeltaTypeEnum.AMOUNT
			if(offer.wholesale){
				def merch = offer.merchant
				def merchUserGroups = MerchantUserGroup.findAllByMerchant(merch)
				def merchUserGroup = null
				merchUserGroups.each { merchantUserGroup ->
					merchantUserGroup.userProfiles.each { userProfile ->
						if( userProfile && userProfile.mobileNumber && userProfile.mobileNumber.equals(user?.mobile)){
							type = merchantUserGroup.deltaType ? merchantUserGroup.deltaType : DeltaTypeEnum.AMOUNT
							sign = merchantUserGroup.deltaSign ? merchantUserGroup.deltaSign : DeltaSignEnum.PLUS
							if(type.equals(DeltaTypeEnum.AMOUNT)) {
								deltaAmount = new Double(sign.toString()+ merchantUserGroup.deltaAmount)
							}else {
								deltaAmount = new Double(merchantUserGroup.deltaAmount)
							}
							merchUserGroup = merchantUserGroup
						}
					}
				}
				if(merchUserGroup){
					offer.pricingGroups.each { group ->
						if(merchUserGroup.groupName.equalsIgnoreCase(group.groupName)
						&& offer.lastUpdated > merchUserGroup.lastUpdated
						){
							sign = group.deltaSign ? group.deltaSign : DeltaSignEnum.PLUS
							type = group.deltaType ? group.deltaType : DeltaTypeEnum.AMOUNT
							if(type.equals(DeltaTypeEnum.AMOUNT)) {
								deltaAmount = new Double(sign.toString()+ group.deltaAmount)
							}else {
								deltaAmount = new Double(group.deltaAmount)
							}
						}
					}
				}else{
					def mPedUserGroup = MPeDUserGroup.findByMerchantAndGroupName(merch, user?.groupName ? user.groupName : servletContext.configuration."${webSite}"."mped_default_group_name"	)
					if(mPedUserGroup){
						sign = mPedUserGroup.deltaSign ? mPedUserGroup.deltaSign : DeltaSignEnum.PLUS
						type = mPedUserGroup.deltaType ? mPedUserGroup.deltaType : DeltaTypeEnum.AMOUNT
						if(type.equals(DeltaTypeEnum.AMOUNT)) {
							deltaAmount = new Double(sign.toString()+ mPedUserGroup.deltaAmount)
						}else {
							deltaAmount = new Double(mPedUserGroup.deltaAmount)
						}
						offer.pricingGroups.each { group ->
							if(mPedUserGroup.groupName.equalsIgnoreCase(group.groupName)
							&& offer.lastUpdated > mPedUserGroup.lastUpdated
							){
								sign = group.deltaSign ? group.deltaSign : DeltaSignEnum.PLUS
								type = group.deltaType ? group.deltaType : DeltaTypeEnum.AMOUNT
								if(type.equals(DeltaTypeEnum.AMOUNT)) {
									deltaAmount = new Double(sign.toString()+ group.deltaAmount)
								}else {
									deltaAmount = new Double(group.deltaAmount)
								}
							}
						}
					}
				}
				Double updatedPrice = 0
				if(type.equals(DeltaTypeEnum.AMOUNT)) {
					updatedPrice = offer.offerPrice + deltaAmount
				}else {
					deltaAmount = (deltaAmount * offer.offerPrice) / 100
					updatedPrice = offer.offerPrice + new Double(sign.toString() + deltaAmount)
				}
				if(updatedPrice < offer.regularPrice) {
					offer.actualOfferPrice = offer.offerPrice
					offer.offerPrice = Math.round(updatedPrice)
				}
			}
		}
		offer
	}


