	private  def calculateCashDiscountPrice(LakshyaMerchantProductOffer offer,Double price){
		CategoryTax productTax=null
		def discount=offer.cashDiscount
		if(discount){
			//if(offer.calculateBeforeTax){
				productTax=getTaxInfoByProduct(offer.product)
				price=calculateBaseCost(price,productTax?.tax)
			//}
			if(offer.cashDiscountType.toString()==DiscountTypeEnum.RELATIVE.toString()){
				discount=(price*discount/100)?.round(2)
			}
			if(discount<price){
				price=price-discount
			}
			//offer.calculateBeforeTax &&
			if(productTax){
				price=caculatePriceTaxInculsive(productTax.tax,price)
			}
		}
		return (price)?.round(2)
	}

