	private def updateEstimatedDeliveryDays(LakshyaMerchantProductOffer offer, String pinCode,  String webSite){

		if(offer.actualQty!=null){
			if(!offer.actualQty && offer.virtualQtyDeliveryDays && offer.virtualQty){
				offer.estimatedDeliveryDays=offer.virtualQtyDeliveryDays
			}
		}
		offer.estimatedDeliveryDays=offer.estimatedDeliveryDays+offer.processingDays;
		// set cutOffTime in estimatedDeliveryDays
		calculateCutOffTime(offer,webSite)
		def location = Location.findByPincode(pinCode)
		//ServiceableDeliveryTime serviceableDeliveryTime = ServiceableDeliveryTime.findByMerchantAndPinCode(offer.merchant,pinCode)
		ServiceableDeliveryTime serviceableDeliveryTime = ServiceableDeliveryTime.findByPinCode(pinCode)
		if(serviceableDeliveryTime){
			if(serviceableDeliveryTime.weekdays){
				calculateEstimatedDliveryOnWeekday(offer,serviceableDeliveryTime,webSite)
				checkHolidayOnDeliveryDay(offer,location.state,webSite)
			}else{
				if(serviceableDeliveryTime.deltaSign==DeltaSignEnum.PLUS){
					offer.estimatedDeliveryDays = offer.estimatedDeliveryDays + serviceableDeliveryTime.deltaDays
				}else{
					offer.estimatedDeliveryDays = offer.estimatedDeliveryDays - serviceableDeliveryTime.deltaDays
				}
			}
		}
		if(serviceableDeliveryTime==null || !serviceableDeliveryTime.weekdays)	{
			//offer = updateEstimatedDaysByNonOpertaionDays(offer,location.state,webSite)
		}

		offer.discard();

		return offer
	}

	private def calculateCutOffTime(LakshyaMerchantProductOffer offer,  String webSite){
		def cutOffTime = servletContext.configuration."${webSite}"."cut_off_time"
		if(cutOffTime){
			def cutOffDate = new Date()
			cutOffDate.set(hourOfDay: Integer.parseInt(cutOffTime), minute: 0, second: 0)
			if(new Date().getTime()>=cutOffDate.getTime()){
				offer.estimatedDeliveryDays = offer.estimatedDeliveryDays+1
				offer.discard();
			}
		}
	}

	private def calculateEstimatedDliveryOnWeekday(LakshyaMerchantProductOffer offer,ServiceableDeliveryTime serviceableDeliveryTime,String webSite){
		def weekdays=serviceableDeliveryTime.weekdays
		def estDate=new Date()+offer.estimatedDeliveryDays;
		int i=0;
		Calendar cal = Calendar.getInstance();
		for(;i<7;i++){
			cal.setTime(estDate);
			int dayOfWeek = cal.get(Calendar.DAY_OF_WEEK) - 1;
			if (dayOfWeek == 0){
				dayOfWeek = 7;
			}
			def day=DayOfWeek.of(dayOfWeek)
			boolean isFound=false;
			weekdays.each{weekday->
				if(weekday.equals(day)){
					isFound=true
				}
			}
			if(isFound){
				break;
			}
			estDate=estDate+1
		}
		offer.estimatedDeliveryDays=offer.estimatedDeliveryDays+i
	}

	private def checkHolidayOnDeliveryDay(LakshyaMerchantProductOffer offer,String state,String webSite){
		def date=new Date()+offer.estimatedDeliveryDays;
		def nonOperationalDays = NonOperationalDays.findAllByStateAndWebSiteAndYear(state,WebSite.get(webSite),(date.year+1900).toString(), [sort: "nonOperationalDate", order: "asc"])*.nonOperationalDate
		int counter=0;
		while(true){
			def d2 = date.format(DateFormatEnum.YYYYMMDD_WITH_DASH.getFormat())
			if(nonOperationalDays.contains(d2)){
				counter++;
				date=date+1
			}else{
				break;
			}
		}
		offer.estimatedDeliveryDays=offer.estimatedDeliveryDays+counter
	}

	private def updateEstimatedDaysByNonOpertaionDays(LakshyaMerchantProductOffer offer,String state,String webSite){
		int count = 0
		int len = offer.estimatedDeliveryDays
		def weekOffDays = servletContext.configuration."${webSite}"."weekly_off_days"
		def weekOffDaysList = []

		if(weekOffDays){
			weekOffDays.tokenize(",").each{ weekOffDaysList << it }
		}

		def cacheMap = [:]

		for(int index = 1; len > 0; index++){
			Date date = new Date()+index;
			count++;
			def isOperational = checkOperational(state,date,webSite,cacheMap,weekOffDaysList)
			if(isOperational){
				len = len-1;
			}
		}

		offer.estimatedDeliveryDays = count;
		offer.discard();
		return offer
	}

	private def checkOperational(String state,Date date,String webSite,Map cacheMap,List weekOffDaysList){

		boolean operational = true;
		int j = 0;
		def d2 = date.format(DateFormatEnum.YYYYMMDD_WITH_DASH.getFormat())
		if(checkWeeklyOff(date,weekOffDaysList)){
			operational = false;
		}else{
			SimpleDateFormat df = new SimpleDateFormat("yyyy");
			def year = df.format(date);
			def nonOperationalDays = cacheMap[year]
			if( null == nonOperationalDays){
				nonOperationalDays = NonOperationalDays.findAllByStateAndWebSiteAndYear(state,WebSite.get(webSite),(year).toString(), [sort: "nonOperationalDate", order: "asc"])
				cacheMap[year] = nonOperationalDays
			}

			if(nonOperationalDays){
				for(; j < nonOperationalDays.size(); j++){
					def data = nonOperationalDays.get(j);
					if(data.nonOperationalDate==d2){
						operational = false;
						//pivot element will be j for next iteration
						break;
					}
				}
			}
		}
		operational
	}

	private def checkWeeklyOff(Date date,List weekOffDaysList){
		boolean flag = false
		Calendar cal = Calendar.getInstance();
		cal.setTime(date);
		if(weekOffDaysList.contains(cal.get(Calendar.DAY_OF_WEEK).toString())){
			flag = true
		}
		return flag
	}

	private def getUpdatedOffer(LakshyaMerchantProductOffer o, Double qty) {
		def newQty = 0, inventoryQty = null, iQty = null, qtyInCart = 0, actualQty = 0, virtualQty = null, qtyDiscountType = DiscountTypeEnum.ABSOLUTE
		if(o.manageInventory==null || o.manageInventory){
			if(o?.productLead) {
				newQty = o?.inventoryQty-qty
			} else {
				newQty = o.qty-qty
			}
			def existingQtyInCart = o.qtyInCart
			def newqtyInCart = existingQtyInCart +  qty
			if(o?.productLead) {
				inventoryQty = (newQty)
			} else {
				iQty = (newQty)
			}
			qtyInCart = (newqtyInCart)
			if(o.actualQty!=null){
				if(o.actualQty>=qty){
					actualQty = (o.actualQty-qty)
				}else{
					def remainQty=qty-o.actualQty
					if(remainQty && o.virtualQty){
						int q=o.virtualQty-remainQty
						virtualQty(q>0?q:0)
					}
				}
			}
			qtyDiscountType = o.qtyDiscountType  ? o.qtyDiscountType : qtyDiscountType
		}else {
			return null
		}
		BasicDBObject update = new BasicDBObject()
		update.put("qtyInCart", qtyInCart)
		update.put("actualQty", actualQty)
		update.put("qtyDiscountType", qtyDiscountType.toString())
		if(inventoryQty) {
			update.put("inventoryQty", inventoryQty)
		}else {
			update.put("qty", iQty)
		}
		if(virtualQty) {
			update.put("virtualQty", virtualQty)
		}
		return update
	}

