			marketplace = lakshyaUtilsService.getMarketplaceProperties(marketplace)?.marketplace
		}
		Map cartSummary=userCartService.deduceCartData(usr,webSite,rsts,cartId,platform,pincode,false,marketplace,dataMap)
		def basketDiscount = 0, surcharge = 0, grandTotal = 0, wholesaleGrandTotal = 0, wholesaleTotalAmount = wholesaleRowTotal, userCoupon = null
		def tagPoints = null, bulkDiscount = 0, firstOrderDiscount, comboDiscount, userCouponList, chequeBounceCharge, chequeBounceChargeList
		def basketCount = 0, basketAmount = 0
		Map suggestedProductMap = [:]
		Map userCartMap = [:]

		if(cartSummary){
			wholesaleRowTotal=cartSummary.total
			wholesaleGrandTotal=cartSummary.grandTotal
			surcharge=cartSummary.deliveryCharges
			userCoupon=cartSummary.userCoupon
			bulkDiscount=cartSummary.bulkDiscount
			basketDiscount=cartSummary.basketDiscount
			basketCount = cartSummary.basketCount
			suggestedProductMap = cartSummary.suggestedProductMap
			basketAmount = cartSummary.basketAmount
			firstOrderDiscount = cartSummary.usrFirstOrderDiscount
			comboDiscount = cartSummary.comboDiscount
			userCouponList = cartSummary.userCouponList
			chequeBounceCharge = cartSummary.chequeBounceCharge
			chequeBounceChargeList = cartSummary.chequeBounceChargeList
		}
		if(marketplace){
			def mProperties = lakshyaUtilsService.getMarketplaceProperties(marketplace)
			marketplace = mProperties?.marketplace
		}
		def walletBalanceMap = walletService.userBalanceWithCreditNotes(usr, webSite, rsts, cartSummary,null,["marketplace":marketplace])
		def walletBalance = walletBalanceMap['balance']
		def cartWallets = walletBalanceMap['cartWallet']

		Map creditNoteMap = [:]
		Double creditNoteValue = 0, remainingWalletAmount = walletAmount ? walletAmount > 0 ? walletAmount : 0 : 0
		cartWallets.each{ k,v ->
			if(v > 0){
				if(remainingWalletAmount >= v){
					creditNoteMap[k] = v
					creditNoteValue += v
					remainingWalletAmount -= v
				}else if(remainingWalletAmount < v){
					creditNoteMap[k] = remainingWalletAmount
					creditNoteValue += remainingWalletAmount
					remainingWalletAmount = 0
				}
			}else{
				creditNoteMap[k] = v
			}
		}

		Double discountAmount=0, cashBackAmount=0;
		if(userCoupon){
			userCouponList = []
			userCouponList << userCoupon
		}
		if(userCouponList){
			userCouponList.each{UserCoupon usrCoupon ->
				Coupon coupon = usrCoupon ? usrCoupon.coupon : null
				Promotion promotion = coupon ? coupon.promotion : null
				if(promotion){
					if(!promotionService.isCashBackPromotion(promotion)){
						discountAmount += usrCoupon.discountAmount
					}else{
						cashBackAmount += usrCoupon.discountAmount
					}
				}
			}
		}

		if(firstOrderDiscount){
			discountAmount += firstOrderDiscount['discountAmount']
		}

		Map cartDiscountMap  = deduceCartDiscount(userCouponList,rsts)
		Map cartLevelDiscount = cartDiscountMap["cartLevelDiscount"]
		Map cartLevelPromotionShare = cartDiscountMap["cartLevelPromotion"]
		Map cartLevelCashBack = cartDiscountMap["cartLevelCashBack"]
		Map firstOrderShareMap = deduceCartFirstOrderDiscount(firstOrderDiscount)

		rsts.each{userCart ->
			def o = (userCart.offer)
			Double unitPrice =  o.offerPrice
			Double rowTotal = unitPrice * userCart.qty
			/*
			 * fetch cart level firstOrder discount share
			 */
			Double firstOrderDiscountForCart = firstOrderShareMap[userCart.id?.toString()]

			//Discount Amount as per item
			Double itemDiscount = 0.0;
			if(discountAmount || basketDiscount){
				itemDiscount=cartLevelDiscount[userCart.id?.toString()]
				itemDiscount = itemDiscount != null ? itemDiscount : 0
				itemDiscount = firstOrderDiscountForCart != null ? (itemDiscount + firstOrderDiscountForCart) : itemDiscount

				Double basketpromoDiscount = 0;
				if(cartId && userCart.suggestedProduct){
					basketpromoDiscount=calculateChargeAmount(basketAmount,rowTotal,basketDiscount)
				}else{
					if(suggestedProductMap[userCart]){
						basketpromoDiscount=calculateChargeAmount(basketAmount,rowTotal,basketDiscount)
					}
				}

				itemDiscount = basketpromoDiscount != null ? itemDiscount + basketpromoDiscount : itemDiscount
			}

			Double comboPromoDiscount = 0

			if(comboDiscount && userCart.comboIds){
				Set comboIds = [] as LinkedHashSet
				userCart.comboIds.each{comboId ->
					SuggestedCombo combo = SuggestedCombo.get(comboId)
					comboPromoDiscount += calculateComboDiscount(userCart.offer, combo)
				}
			}

			//Surcharge Amount as per item
			Double itemSurcharge
			if(surcharge){
				itemSurcharge=calculateChargeAmount(wholesaleRowTotal,rowTotal,surcharge)
			}

			double itemChequeBounceCharge
			if(chequeBounceCharge){
				itemChequeBounceCharge=calculateChargeAmount(wholesaleRowTotal,rowTotal,chequeBounceCharge)
			}

			if(itemDiscount){
				rowTotal=rowTotal-itemDiscount
			}
			if(comboPromoDiscount){
				rowTotal = rowTotal - comboPromoDiscount
			}
			if(itemSurcharge){
				rowTotal=rowTotal+itemSurcharge
			}

			if(itemChequeBounceCharge){
				rowTotal=rowTotal+itemChequeBounceCharge
			}

			Double saleTotal = rowTotal != null ? new Double(rowTotal.toString()) : 0.0
			Double wallet =  calculateChargeAmount(new Double(wholesaleGrandTotal.toString()).round(2),saleTotal.round(2),remainingWalletAmount)
			userCartMap[userCart.id] = userCartMap[userCart.id] ? userCartMap[userCart.id] : [:]
			userCartMap[userCart.id]['grossPayableAmount'] = (saleTotal - (wallet ? wallet : 0.0)).round(2)
			userCartMap[userCart.id]['netPayableAmount'] = (saleTotal - (wallet ? wallet : 0.0)).round(2)
		}

		if(rsPaymentMethodUsed ) {
			wholesaleGrandTotal = wholesaleGrandTotal ? wholesaleGrandTotal : 0
			walletAmount = walletAmount ? walletAmount : 0
			Map rstsMap = getNetPayableAmounts(rsts, (wholesaleGrandTotal - remainingWalletAmount), rsPaymentMethodUsed, usr, webSite, cartId, userCartMap)
			rsts = rstsMap ? rstsMap['rsts'] : rsts
			userCartMap = rstsMap ? rstsMap['cartMap'] : userCartMap
		}
		if(creditNoteValue != null && creditNoteValue> 0 ){
			Double creditNoteAmount = creditNoteValue
			rsts.each{userCart ->
				Double amount = userCartMap[userCart.id]['netPayableAmount']
				def creditNoteAmounts = creditNoteMap[userCart.id]
				if(creditNoteAmounts > 0 && creditNoteAmount > 0 ) {
					Double saleCNAmount = amount
					if(creditNoteAmount > amount){
						creditNoteAmount -= amount
					}else{
						saleCNAmount = creditNoteAmount
						creditNoteAmount = 0
					}
					Double netAmount  = amount - saleCNAmount
					userCartMap[userCart.id]['netPayableAmount'] = netAmount
					userCartMap[userCart.id]['grossPayableAmount'] = userCartMap[userCart.id]['grossPayableAmount'] - saleCNAmount
				}
			}
		}
		def rstsMap = [:]
		rstsMap['rsts'] = rsts
		rstsMap['cartSummary'] = cartSummary
		rstsMap = calculateAdvanceAmountIfApplicable(rstsMap, userCartMap, rsPaymentMethodUsed, usr, webSite, cartId)
		return rstsMap
	}

	private def getNetPayableAmounts(def rsts, Double payableAmount, String rsPaymentMethodUsed, def usr, String webSite, String cartId, Map userCartMap) {
		PaymentTypeInformation paymentTypeInfo = lakshyaOrderService.getPaymentTypeInfo(payableAmount, rsPaymentMethodUsed, usr, cartId, webSite)
		boolean isMinOrderValueApplicable = paymentTypeInfo ? paymentTypeInfo.isMinOrderValueApplicable : false
		boolean isMaxOrderValueApplicable = paymentTypeInfo ? paymentTypeInfo.isMaxOrderValueApplicable : false
		boolean isMinMaxOrderValueApplicable = paymentTypeInfo ? paymentTypeInfo.isMinMaxOrderValueApplicable : false


		if(isMinOrderValueApplicable || isMaxOrderValueApplicable || isMinMaxOrderValueApplicable) {
			if(paymentTypeInfo?.surchargeDiscount?.toString()?.equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.DISCOUNT.toString(),SurchargeDiscountTypeEnum.ABSOLUTE.toString(),paymentTypeInfo, userCartMap)
			} else if(paymentTypeInfo?.surchargeDiscount.toString().equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.DISCOUNT.toString(),SurchargeDiscountTypeEnum.PERCENTAGE.toString(),paymentTypeInfo, userCartMap)
			} else if(paymentTypeInfo?.surchargeDiscount?.toString()?.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.SURCHARGE.toString(),SurchargeDiscountTypeEnum.ABSOLUTE.toString(),paymentTypeInfo, userCartMap)
			} else if(paymentTypeInfo?.surchargeDiscount?.toString()?.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.SURCHARGE.toString(),SurchargeDiscountTypeEnum.PERCENTAGE.toString(),paymentTypeInfo, userCartMap)
			}
		}
		return null
	}

	private def calcAddedDiscSurchargeValues(def rsts, Double netPayableAmount, String discSurcharge, String discSurchargeType, PaymentTypeInformation paymentTypeInfo, Map userCartMap) {
		Double payableAmount = netPayableAmount
		Double additionalDiscount = 0, additionalSurcharge = 0
		if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) && discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
			if((netPayableAmount) > paymentTypeInfo.surchargeDiscountValue) {
				additionalDiscount = paymentTypeInfo.surchargeDiscountValue
			} else {
				additionalDiscount = netPayableAmount
			}
		} else if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) &&
		discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
			netPayableAmount = (netPayableAmount * paymentTypeInfo.surchargeDiscountValue/100)
			additionalDiscount = netPayableAmount.round(2)
		} else if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
		discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
			additionalSurcharge = paymentTypeInfo.surchargeDiscountValue
		} else if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
		discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
			netPayableAmount = (netPayableAmount * paymentTypeInfo.surchargeDiscountValue/100)
			additionalSurcharge = netPayableAmount.round(2)
		}
		rsts.each{userCart ->
			Double grossPayableAmount = userCartMap[userCart.id]['grossPayableAmount']
			Double cartAdditionalDiscount = 0, cartAdditionalSurcharge = 0
			cartAdditionalDiscount = (grossPayableAmount/payableAmount)*additionalDiscount
			cartAdditionalSurcharge = (grossPayableAmount/payableAmount)*additionalSurcharge
			Double netAmount = grossPayableAmount - cartAdditionalDiscount + cartAdditionalSurcharge
			userCartMap[userCart.id]['netPayableAmount'] = netAmount.round(2)
		}
		Map map = [:]
		map['rsts'] = rsts
		map['cartMap'] = userCartMap
		return map
	}

