	@Retryable(maxAttempts = 5,backoff = @Backoff(4000L))
	def saveCart(def userCart,userCartMap,def advAmountPayable){

		if(userCart){
			userCart.refresh();
			userCart.netPayableAmount = userCartMap[userCart.id]['netPayableAmount']
			userCart.grossPayableAmount = userCartMap[userCart.id]['grossPayableAmount']
			userCart.advAmountPayable = advAmountPayable.round(2)
			userCart.isAdvanceAmountApplicable = advAmountPayable > 0
			userCart.save(flush:true, deepValidate:false)
		}
	}

	def calculateComboDiscount(MerchantProductOffer offer,SuggestedCombo combo){
		def discountValue = 0
		def offerPrice = 0
		combo.offers.each{ off ->
			if(offer.id.toString().equals(off.id.toString())){
				discountValue = off.comboDiscountValue ? off.comboDiscountValue : 0
				offerPrice = off.offerPrice;
			}
		}
		if(discountValue == 0){
			discountValue = combo.comboDiscount*offerPrice/combo.totalPrice;
		}else if(combo.discountType.toString().equalsIgnoreCase(DeltaTypeEnum.PERCENTAGE.toString())){
			discountValue = (discountValue/100)*combo.comboDiscount;
		}
		return discountValue.round(2);
	}

	def isPayTMApplicable(Double amount, String webSite) {
		String transactionAmount =servletContext.configuration."${webSite}".'paytm_transaction_amount'
		String transactionCount =servletContext.configuration."${webSite}".'paytm_transaction_count'
		String dailyTransactionAmount =servletContext.configuration."${webSite}".'paytm_daily_transaction_amount'
		Double allowedTxnAmount = transactionAmount ? Double.parseDouble(transactionAmount.toString()) : 0
		Boolean retVal = false
		Map map = [:]
		if(amount <= allowedTxnAmount) {
			Double allowedTxnCount = transactionCount ? Double.parseDouble(transactionCount.toString()) : 0
			if(allowedTxnCount) {
				Double allowedDailyTxnAmount =  dailyTransactionAmount ? Double.parseDouble(dailyTransactionAmount.toString()) : 0
				if(allowedDailyTxnAmount) {
					Date today = new Date()
					Calendar cal = Calendar.getInstance()
					cal.setTime(today)
					Date date = lakshyaUtilsService.getStartDate(cal)
					def txnCount = 1
					Double txnAmount = amount
					PayTMLimit limit = PayTMLimit.findByValidFromDate(date)
					if(limit) {
						txnCount += limit.transactionCount
						txnAmount += limit.dailyTransactionAmountUsed
					}
					if(txnCount <= allowedTxnCount && txnAmount <= allowedDailyTxnAmount) {
						retVal =  true
					}
				}
			}
		}
		return retVal
	}

	def getAddress(def usr, def selectedAddressId, wst){
		def addresses = UserAddressExtension.findAllByUserAndWebSite(usr, WebSite.get(wst), [sort: "selectedAddress",order: "desc"])
		def address = []
		def addressmap = [:]
		def selectedaddressmap = [:]
		addresses.each{ ad ->
			addressmap = [:]
			addressmap.id = ad.id
			addressmap.salutation = ad.salutation
			addressmap.firstName = ad.firstName
			addressmap.lastName = ad.lastName
			addressmap.company = ad.gstin ? ad.company : usr?.company
			addressmap.addressLine1 = ad.addressLine1
			addressmap.addressLine2 = ad.addressLine2
			addressmap.state = ad.state
			addressmap.city = ad.city
			addressmap.area = ad.area
			addressmap.pinCode = ad.pinCode
			addressmap.phone = ad.phone
			addressmap.gstin = ad.gstin
			addressmap.defaultAddress = ad.defaultAddress
			addressmap.selectedAddress = ad.selectedAddress
			addressmap.landmark = ad.landmark
			addressmap.latitude  = ad.latitude
			addressmap.longitude = ad.longitude

			if(ad.selectedAddress && selectedAddressId){
				ad.selectedAddress = false
				ad.save(flush:true, deepValidate:false)
			}
			if(ad.selectedAddress){
				selectedaddressmap = addressmap
			}
			if(selectedAddressId && selectedAddressId.equals(ad.id?.toString())){
				ad.selectedAddress = true
				ad.save(flush:true, deepValidate:false)
				selectedaddressmap = addressmap
			}
			addressmap.isSelectedAddress = ad.selectedAddress?ad.selectedAddress:false
			if(!ad.selectedAddress){
				address << addressmap
			}
		}
		def listAddress = []
		if(!selectedaddressmap.isEmpty()){
			listAddress << selectedaddressmap
		}
		address.each { ad -> listAddress << ad }

		if(!selectedAddressId){
			address = []
			def dlistAddress = []
			listAddress.each{ addr ->
				if(addr.defaultAddress){
					addr.isSelectedAddress = true
					dlistAddress << addr
				}else{
					addr.isSelectedAddress = false
					address << addr
				}
			}
			address.each { ad -> dlistAddress << ad }
			return dlistAddress

		}

		return listAddress
	}

	def setAdditionalDiscountSurcharge(def responseMap, def usr, def wst, def cartId){
		def grandTotal = responseMap.paymentMap.grandTotal
		def paymentMethodType = responseMap.paymentMap.paymentMethodType
		def paymentInfo = lakshyaOrderService.getAdditionalDiscountSurchargeInfo(grandTotal, paymentMethodType, usr, cartId, wst)
		def additionalType
		def additonalDiscount
		def additionalSurcharge
		if(paymentInfo){
			paymentInfo = paymentInfo.tokenize(':')
			DecimalFormat df2 = new DecimalFormat(".")

			additionalType = paymentInfo[1].toString()
			if("Surcharge".equals(additionalType)){
				String srchg = paymentInfo[0]?.toString()
				additionalSurcharge = new Double(srchg)
				responseMap.paymentMap.additionalSurcharge = additionalSurcharge
				responseMap.paymentMap.grandTotal = grandTotal + additionalSurcharge
			}
			if("Discount".equals(additionalType)){
				String discnt = paymentInfo[0]?.toString()
				additonalDiscount = new Double(discnt)
				responseMap.paymentMap.additonalDiscount = additonalDiscount
				responseMap.paymentMap.grandTotal = grandTotal - additonalDiscount
			}
			responseMap.paymentMap.grandTotal = Utils.setScale(responseMap.paymentMap.grandTotal)
			//paymentMap["summary"] = summary
		}
		return responseMap
	}

	def updateFirmName(User user, String firmName, String gstin){
		def sale = Sale.createCriteria().list(){
			eq('user', user)
			not{'in'('status', (['PENDING', 'CANCELLED']))}
		}
		if(!sale){
			def userAddresses = UserAddress.createCriteria().list(){
				eq('user', user)
				ne('company', firmName)
			}
			userAddresses.each{UserAddress address->
				address.company = firmName
				address.gstin = gstin
				address.save flush:true
			}
			if(!user.company.toString().equals(firmName)){
				user.company = firmName
				user.gstin = gstin
				user.save flush:true
			}
		}
	}

