	def makeWalletOrderByMinOrderValue(def creditWallets){
		List creditWalletsWithoutMinOrderValue = []
		List creditWalletList = []
		TreeMap<Double, Wallet> minOrderValues =new TreeMap<>()
		creditWallets.each{ cw ->
			if(cw.minimumOrderValue && cw.minimumOrderValue > 0){
				minOrderValues.put(cw.minimumOrderValue, cw)
			}else{
				creditWalletsWithoutMinOrderValue << cw
			}
		}

		for(Map.Entry<Double, Wallet> entry : minOrderValues.entrySet()) {
			creditWalletList << entry.value
		}


		creditWalletsWithoutMinOrderValue.each { cwwmo ->
			creditWalletList << cwwmo
		}
		return creditWalletList
	}

