	/**
	 * @param webSite
	 * @param usr
	 * @return
	 */
	def getRqAllowedMethods(def webSite, def usr ,def pinCode =null, def isElectricalOrder = false){

		def allowedPaymentMethodsMap = servletContext.configuration."${webSite}"."consolidated_payment_methods_allowed"

		User userExt = User.get(usr.id)
		MasterCategory userCategory = lakshyaUtilsService.findUserCategory(userExt)
		List allowedPaymentMethods = CategoryPaymentMode.findByCategory(userCategory)?.paymentModes

		if(!allowedPaymentMethods){
			allowedPaymentMethods = []
			allowedPaymentMethods.addAll(allowedPaymentMethodsMap.tokenize(","))
		}

		//find PinCode of the user
		/*def user = User.get(springSecurityService.principal.id)
		 def pinCode = user?.pinCode*/

		//taking intersection of payment modes of category and pincodewise
		def allowedPaymentMethodsForPincode = []
		allowedPaymentMethodsForPincode = pinCode ? PincodePaymentMode.findByPinCodeLike(pinCode+"%")?.paymentModes : null

		if(allowedPaymentMethodsForPincode){
			def allowedPaymentMethodsForPincodeSet =allowedPaymentMethodsForPincode.toSet()
			if(allowedPaymentMethods){
				allowedPaymentMethods.retainAll(allowedPaymentMethodsForPincodeSet);
			}
		}

		def electricalOrderPaymentModes = appConfigParamService.getMorePaymentMethods(webSite);
		if(isElectricalOrder){
			electricalOrderPaymentModes.each{mode->
				if(!allowedPaymentMethods.contains(mode)){
					allowedPaymentMethods << mode
				}else{
					allowedPaymentMethods.remove(mode)
					allowedPaymentMethods << mode
				}
			}
		}

		def rqAllowedMethods = []
		def userPDCDays = userExt.chequePDCDays
		userPDCDays = userPDCDays != null  && userPDCDays > 0 ? userPDCDays : null
		//def userExt = User.get(usr.id)

		allowedPaymentMethods.each{ allowedMethod ->
			def methodName = PaymentMethodEnum.valueOf(allowedMethod)
			if(methodName == PaymentMethodEnum.POSTDATEDCHEQUE ){
				if((isElectricalOrder && !userPDCDays) || userPDCDays){
					rqAllowedMethods << methodName
				}
			}else if(methodName != PaymentMethodEnum.CREDITCARD && methodName != PaymentMethodEnum.DEBITCARD){
				rqAllowedMethods << methodName
			}
		}

		def allowedMethods = []
		Double userCDCLimit = userExt.cdcLimit
		if(!rqAllowedMethods.isEmpty()){
			def blocked = isChequeCodBlocked(userExt, webSite)
			Boolean isChequeBlocked = blocked['cheque']
			Boolean isCodBlocked = blocked['cod']
			if(isElectricalOrder){
				def myAllowedMethods = rqAllowedMethods
				if(isCodBlocked){
					rqAllowedMethods = []
					myAllowedMethods.each{methodName ->
						if(methodName != PaymentMethodEnum.CASHONDELIVERY){
							rqAllowedMethods << methodName
						}
					}
				}
				if(userCDCLimit > 0){
					rqAllowedMethods.each{methodName ->
						if(methodName == PaymentMethodEnum.CHEQUE || methodName == PaymentMethodEnum.POSTDATEDCHEQUE){
							if((userPDCDays && methodName == PaymentMethodEnum.POSTDATEDCHEQUE) || (!userPDCDays && methodName == PaymentMethodEnum.CHEQUE)){
								allowedMethods << methodName
							}
						}else{
							allowedMethods << methodName
						}
					}
				}else{
					rqAllowedMethods.each{methodName -> allowedMethods << methodName }
				}

			}else{
				if((isChequeBlocked && !isCodBlocked) || (userExt.codAmountLimit == null && userExt.actualChequeLimit == null)){
					rqAllowedMethods.each{methodName ->
						if(methodName != PaymentMethodEnum.CHEQUE && methodName != PaymentMethodEnum.POSTDATEDCHEQUE){
							allowedMethods << methodName
						}
					}
				}else if(!isChequeBlocked ){
					rqAllowedMethods.each{methodName ->
						if(methodName == PaymentMethodEnum.CASHONDELIVERY || (userPDCDays && methodName == PaymentMethodEnum.CHEQUE)){	}else{
							allowedMethods << methodName
						}
					}
				}else{
					rqAllowedMethods.each{methodName ->
						if(methodName != PaymentMethodEnum.CHEQUE && methodName != PaymentMethodEnum.POSTDATEDCHEQUE && methodName != PaymentMethodEnum.CASHONDELIVERY){
							allowedMethods << methodName
						}
					}
				}
			}
		}else{
			allowedPaymentMethodsMap.tokenize(",").each{allowedMethod ->
				def methodName = PaymentMethodEnum.valueOf(allowedMethod)
				if(!(methodName == PaymentMethodEnum.CREDIT || methodName == PaymentMethodEnum.POSTDATEDCHEQUE || methodName == PaymentMethodEnum.CHEQUE ||
				methodName == PaymentMethodEnum.CASHONDELIVERY || methodName == PaymentMethodEnum.NEFTRTGS || methodName == PaymentMethodEnum.RUPIFICREDIT)  ){
					allowedMethods << methodName
				}
			}
		}
		String rupifiEnabled = servletContext.configuration."${webSite}"."rupifi_enabled"
		if(rupifiEnabled.equals("true")) {
			allowedMethods << PaymentMethodEnum.RUPIFICREDIT
			/*def rupifiUser = RupifiUser.findAllByUser(usr)
			if (rupifiUser.size() > 0 && rupifiUser.active[0] == true) {
				allowedMethods << PaymentMethodEnum.RUPIFICREDIT
			}*/
		}

		boolean paylaterEnabled = servletContext.configuration."${webSite}"."paylater_enabled" ? servletContext.configuration."${webSite}"."paylater_enabled"?.toBoolean() : false
		if(!paylaterEnabled) {
			if(allowedMethods?.contains(PaymentMethodEnum.PAYLATER)) {
				allowedMethods?.remove(PaymentMethodEnum.PAYLATER)
			}
		}
		rqAllowedMethods = []
		rqAllowedMethods.addAll(allowedMethods)
		/*def methodsToShow = []
		def cdcToStop = isUserFirstOrder(usr)
		rqAllowedMethods.each{methodName ->
			if(!(cdcToStop && (methodName == PaymentMethodEnum.CREDIT || methodName == PaymentMethodEnum.POSTDATEDCHEQUE || methodName == PaymentMethodEnum.CHEQUE))){
				methodsToShow << methodName
			}
		}
		return methodsToShow;*/

		return rqAllowedMethods;
	}

