			//if(cat == 'Mobiles') {
			//	totalAmount += userCartMap[userCart.id]['netPayableAmount']
			//}
			if (o?.product?.attributes?.prebook && o?.prebookPrice) {
				totalAmount += userCartMap[userCart.id]['netPayableAmount']
			}
		}
		rsts.each{userCart ->
