				userCart.netPayableAmount = userCartMap[userCart.id]['netPayableAmount']
				userCart.grossPayableAmount = userCartMap[userCart.id]['grossPayableAmount']
				Double netPayableAmount = userCart.netPayableAmount
				Double netAmountPayable = netPayableAmount / totalAmount
				Double advAmountPayable = advAmount
				String cat = o.product.attributes['mastercategory']
				//if(cat == 'Mobiles') {
				/*if(payTM) {
                    if (payTM?.advAmountType==DeltaTypeEnum.PERCENTAGE) {
                        advAmountPayable = (netPayableAmount * advAmount) / 100
                    } else {
