				def lead = sale.offer?.productLead;
				lead.rfqStatus = RfqStatusEnum.CONVERTED
				lead.save(flush:true, failOnError:true, deepValidate:false)

				sale?.offer?.leadStatus = RfqStatusEnum.CONVERTED
				sale?.offer?.purchaseDate = new Date()
				def offer = LakshyaMerchantProductOffer.get(sale?.offer?.id);
				offer?.leadStatus = RfqStatusEnum.CONVERTED
				offer.save(flush:true, failOnError:true, deepValidate:false)

				if(!LeadOffer.countByOffer(sale.offer)) {
					new LeadOffer(
							firstSale:sale,
							offer:sale.offer
							).save(flush:true, failOnError:true, deepValidate:false)
				}
			}

		} catch (Exception e){
