	def itemWiseShippingCost(Double surcharge, List cartList){
	def cartWeightMap=[:]
		def cartLevelShare=[:]
		def tWeight=0
		cartList.each {cart ->
		if (cart) {
			def weight=cart.offer.product.attributes['weight'] ?: cart.offer.product.attributes['weightkg']
			try {
				if (weight) {
					weight = weight.toDouble() * cart.qty
					cartWeightMap[cart?.id?.toString()] = weight
					tWeight += weight
				}
			}catch(Exception e){}
		}
	}
		def perKgWeight=surcharge/tWeight;
		cartWeightMap.each{ k,v ->
			cartLevelShare[k]=v *perKgWeight.round(2)

		}
		return cartLevelShare
	}

