	def deduceCartDiscount(def userCouponList, def cartList, def creditNoteMap = [:]){

		Map cartLevelAmount = [:]
		Map cartLevelPromotion = [:]
		cartList.each{ cartItem ->
			if(cartItem){
				Double unitPrice =  cartItem?.offer?.offerPrice
				Double rowTotal = unitPrice * cartItem?.qty
				cartLevelAmount[cartItem?.id?.toString()] = rowTotal
			}
		}

		//cart level share
		Map cartLevelDiscount = [:]
		Map cartLevelCashBack = [:]
		if(userCouponList){
			userCouponList.each{userCoupon ->
				if(userCoupon){
					def userCartList = userCoupon.userCartList;
					if(userCartList && userCoupon.discountAmount){
						Map cartLevelShare = findDiscountShare(userCoupon?.discountAmount,userCartList,cartLevelAmount, creditNoteMap);
						//userCoupon.userCartList = null;
						cartLevelShare.each{ k, v ->
							//cart level promotion & share
							def data = cartLevelPromotion[k]
							if(null == data){
								data = [:]
							}
							def proName = userCoupon?.coupon?.promotion?.promotionName.replaceAll("\\.", "U+2022")
							data[proName]= v

							cartLevelPromotion[k] = data;

							if(promotionService.isCashBackPromotion(userCoupon.coupon.promotion)){
								//cart level cashBack
								def discount = cartLevelCashBack[k];
								if(discount){
									v += discount;
								}
								cartLevelCashBack[k]= v;
							}else{
								//cart level discount
								def discount = cartLevelDiscount[k];
								if(discount){
									v += discount;
								}
								cartLevelDiscount[k]= v;
							}

						}
					}
				}

			}
		}

		//wrapper object
		def cartPromotionData = [:]
		cartPromotionData["cartLevelDiscount"] = cartLevelDiscount
		cartPromotionData["cartLevelPromotion"] = cartLevelPromotion
		cartPromotionData["cartLevelCashBack"] = cartLevelCashBack
		return cartPromotionData;
	}

