	//	def getNextSequence(String name) throws Exception{
	def getNextSequence(String name) {
		try {
			BasicDBObject find = new BasicDBObject();
			find.put("_id", name);
			BasicDBObject update = new BasicDBObject();
			update.put("\$inc", new BasicDBObject("seq", 1));
			def obj =  SequenceId.collection.findOneAndUpdate(find, update);
			if(obj==null){
				obj=createSequence(name)
			}
			return obj.seq
		} catch (Exception e){
			log.error("Error in Next Sequence {}",e)
		}
	}
	def createSequence(String name){
		SequenceId seqId=new SequenceId(seq:2);
		seqId.id=name
		seqId.save(flush:true, failOnError:true, deepValidate:false)
		seqId.seq=seqId.seq-1
		return 	seqId
	}

