				Promotion promotion = coupon ? coupon.promotion : null
				if(promotion){
					if(!promotionService.isCashBackPromotion(promotion)){
						discountAmount += usrCoupon.discountAmount
					}else{
						cashBackAmount += usrCoupon.discountAmount
					}
				}
			}
		}

		if(firstOrderDiscount){
			discountAmount += firstOrderDiscount['discountAmount']
		}

		Map cartDiscountMap  = deduceCartDiscount(userCouponList,rsts)
		Map cartLevelDiscount = cartDiscountMap["cartLevelDiscount"]
		Map cartLevelPromotionShare = cartDiscountMap["cartLevelPromotion"]
		Map cartLevelCashBack = cartDiscountMap["cartLevelCashBack"]
		Map firstOrderShareMap = deduceCartFirstOrderDiscount(firstOrderDiscount)

		rsts.each{userCart ->
			def o = (userCart.offer)
			Double unitPrice =  o.offerPrice
			Double rowTotal = unitPrice * userCart.qty
			/*
			 * fetch cart level firstOrder discount share
			 */
			Double firstOrderDiscountForCart = firstOrderShareMap[userCart.id?.toString()]

			//Discount Amount as per item
			Double itemDiscount = 0.0;
			if(discountAmount || basketDiscount){
				itemDiscount=cartLevelDiscount[userCart.id?.toString()]
				itemDiscount = itemDiscount != null ? itemDiscount : 0
				itemDiscount = firstOrderDiscountForCart != null ? (itemDiscount + firstOrderDiscountForCart) : itemDiscount

				Double basketpromoDiscount = 0;
				if(cartId && userCart.suggestedProduct){
					basketpromoDiscount=calculateChargeAmount(basketAmount,rowTotal,basketDiscount)
				}else{
					if(suggestedProductMap[userCart]){
						basketpromoDiscount=calculateChargeAmount(basketAmount,rowTotal,basketDiscount)
					}
				}

				itemDiscount = basketpromoDiscount != null ? itemDiscount + basketpromoDiscount : itemDiscount
			}

			Double comboPromoDiscount = 0

			if(comboDiscount && userCart.comboIds){
				Set comboIds = [] as LinkedHashSet
				userCart.comboIds.each{comboId ->
					SuggestedCombo combo = SuggestedCombo.get(comboId)
					comboPromoDiscount += calculateComboDiscount(userCart.offer, combo)
				}
			}

			//Surcharge Amount as per item
			Double itemSurcharge
			if(surcharge){
				itemSurcharge=calculateChargeAmount(wholesaleRowTotal,rowTotal,surcharge)
			}

			double itemChequeBounceCharge
			if(chequeBounceCharge){
				itemChequeBounceCharge=calculateChargeAmount(wholesaleRowTotal,rowTotal,chequeBounceCharge)
			}

			if(itemDiscount){
				rowTotal=rowTotal-itemDiscount
			}
			if(comboPromoDiscount){
				rowTotal = rowTotal - comboPromoDiscount
			}
			if(itemSurcharge){
				rowTotal=rowTotal+itemSurcharge
			}

			if(itemChequeBounceCharge){
				rowTotal=rowTotal+itemChequeBounceCharge
			}

			Double saleTotal = rowTotal != null ? new Double(rowTotal.toString()) : 0.0
			Double wallet =  calculateChargeAmount(new Double(wholesaleGrandTotal.toString()).round(2),saleTotal.round(2),remainingWalletAmount)
			userCartMap[userCart.id] = userCartMap[userCart.id] ? userCartMap[userCart.id] : [:]
			userCartMap[userCart.id]['grossPayableAmount'] = (saleTotal - (wallet ? wallet : 0.0)).round(2)
			userCartMap[userCart.id]['netPayableAmount'] = (saleTotal - (wallet ? wallet : 0.0)).round(2)
		}

		if(rsPaymentMethodUsed ) {
			wholesaleGrandTotal = wholesaleGrandTotal ? wholesaleGrandTotal : 0
			walletAmount = walletAmount ? walletAmount : 0
			Map rstsMap = getNetPayableAmounts(rsts, (wholesaleGrandTotal - remainingWalletAmount), rsPaymentMethodUsed, usr, webSite, cartId, userCartMap)
			rsts = rstsMap ? rstsMap['rsts'] : rsts
			userCartMap = rstsMap ? rstsMap['cartMap'] : userCartMap
		}
		if(creditNoteValue != null && creditNoteValue> 0 ){
			Double creditNoteAmount = creditNoteValue
			rsts.each{userCart ->
				Double amount = userCartMap[userCart.id]['netPayableAmount']
				def creditNoteAmounts = creditNoteMap[userCart.id]
				if(creditNoteAmounts > 0 && creditNoteAmount > 0 ) {
					Double saleCNAmount = amount
					if(creditNoteAmount > amount){
						creditNoteAmount -= amount
					}else{
						saleCNAmount = creditNoteAmount
						creditNoteAmount = 0
					}
					Double netAmount  = amount - saleCNAmount
					userCartMap[userCart.id]['netPayableAmount'] = netAmount
					userCartMap[userCart.id]['grossPayableAmount'] = userCartMap[userCart.id]['grossPayableAmount'] - saleCNAmount
				}
			}
		}
		def rstsMap = [:]
		rstsMap['rsts'] = rsts
		rstsMap['cartSummary'] = cartSummary
		rstsMap = calculateAdvanceAmountIfApplicable(rstsMap, userCartMap, rsPaymentMethodUsed, usr, webSite, cartId)
		return rstsMap
	}

	private def getNetPayableAmounts(def rsts, Double payableAmount, String rsPaymentMethodUsed, def usr, String webSite, String cartId, Map userCartMap) {
		PaymentTypeInformation paymentTypeInfo = lakshyaOrderService.getPaymentTypeInfo(payableAmount, rsPaymentMethodUsed, usr, cartId, webSite)
		boolean isMinOrderValueApplicable = paymentTypeInfo ? paymentTypeInfo.isMinOrderValueApplicable : false
		boolean isMaxOrderValueApplicable = paymentTypeInfo ? paymentTypeInfo.isMaxOrderValueApplicable : false
		boolean isMinMaxOrderValueApplicable = paymentTypeInfo ? paymentTypeInfo.isMinMaxOrderValueApplicable : false


		if(isMinOrderValueApplicable || isMaxOrderValueApplicable || isMinMaxOrderValueApplicable) {
			if(paymentTypeInfo?.surchargeDiscount?.toString()?.equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.DISCOUNT.toString(),SurchargeDiscountTypeEnum.ABSOLUTE.toString(),paymentTypeInfo, userCartMap)
			} else if(paymentTypeInfo?.surchargeDiscount.toString().equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.DISCOUNT.toString(),SurchargeDiscountTypeEnum.PERCENTAGE.toString(),paymentTypeInfo, userCartMap)
			} else if(paymentTypeInfo?.surchargeDiscount?.toString()?.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.SURCHARGE.toString(),SurchargeDiscountTypeEnum.ABSOLUTE.toString(),paymentTypeInfo, userCartMap)
			} else if(paymentTypeInfo?.surchargeDiscount?.toString()?.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
			paymentTypeInfo?.surchargeDiscountType?.toString()?.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
				return calcAddedDiscSurchargeValues(rsts, payableAmount, SurchargeDiscountEnum.SURCHARGE.toString(),SurchargeDiscountTypeEnum.PERCENTAGE.toString(),paymentTypeInfo, userCartMap)
			}
		}
		return null
	}

	private def calcAddedDiscSurchargeValues(def rsts, Double netPayableAmount, String discSurcharge, String discSurchargeType, PaymentTypeInformation paymentTypeInfo, Map userCartMap) {
		Double payableAmount = netPayableAmount
		Double additionalDiscount = 0, additionalSurcharge = 0
		if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) && discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
			if((netPayableAmount) > paymentTypeInfo.surchargeDiscountValue) {
				additionalDiscount = paymentTypeInfo.surchargeDiscountValue
			} else {
				additionalDiscount = netPayableAmount
			}
		} else if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.DISCOUNT.toString()) &&
		discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
			netPayableAmount = (netPayableAmount * paymentTypeInfo.surchargeDiscountValue/100)
			additionalDiscount = netPayableAmount.round(2)
		} else if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
		discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.ABSOLUTE.toString())) {
			additionalSurcharge = paymentTypeInfo.surchargeDiscountValue
		} else if(discSurcharge.equalsIgnoreCase(SurchargeDiscountEnum.SURCHARGE.toString()) &&
		discSurchargeType.equalsIgnoreCase(SurchargeDiscountTypeEnum.PERCENTAGE.toString())) {
			netPayableAmount = (netPayableAmount * paymentTypeInfo.surchargeDiscountValue/100)
			additionalSurcharge = netPayableAmount.round(2)
		}
		rsts.each{userCart ->
			Double grossPayableAmount = userCartMap[userCart.id]['grossPayableAmount']
			Double cartAdditionalDiscount = 0, cartAdditionalSurcharge = 0
			cartAdditionalDiscount = (grossPayableAmount/payableAmount)*additionalDiscount
			cartAdditionalSurcharge = (grossPayableAmount/payableAmount)*additionalSurcharge
			Double netAmount = grossPayableAmount - cartAdditionalDiscount + cartAdditionalSurcharge
			userCartMap[userCart.id]['netPayableAmount'] = netAmount.round(2)
		}
		Map map = [:]
		map['rsts'] = rsts
		map['cartMap'] = userCartMap
		return map
	}

	private def calculateAdvanceAmountIfApplicable(Map rstsMap, Map userCartMap, String rsPaymentMethod, def usr, def webSite, def cartId) {
		List rsts = rstsMap['rsts']
		def categoryList = []
		Double advAmount = 0
		rsts.each{userCart ->
			def o = userCart.offer
			String category = o.product.attributes['mastercategory']
			categoryList << category
			if (userCart?.offer?.product?.attributes?.prebook && userCart?.offer?.prebookPrice) {
				advAmount += (userCart?.qty*userCart?.offer?.prebookPrice)
			}
		}
		Double grossTotal = 0, additionalDiscount = 0, additionalSurcharge = 0, advanceAmount = 0

		//Changed as per LTD-1408
		//MasterCategory category = MasterCategory.findByMasterCategory("Mobiles")
		//CategoryPayTMConfiguration payTM = CategoryPayTMConfiguration.findByCategoryAndPaymentMode(category,rsPaymentMethod)
		//Double advAmount = payTM ? payTM.advAmount :0//0
		/*if(categoryList.contains("Mobiles")){
			advAmount = payTM ? payTM.advAmount :0
		}*/

		def totalAmount = 0
		rsts.each{userCart ->
			def o = userCart.offer
			String cat = o.product.attributes['mastercategory']
			//if(cat == 'Mobiles') {
			//	totalAmount += userCartMap[userCart.id]['netPayableAmount']
			//}
			if (o?.product?.attributes?.prebook && o?.prebookPrice) {
				totalAmount += userCartMap[userCart.id]['netPayableAmount']
			}
		}
		rsts.each{userCart ->
			//userCart.refresh()
			def o = userCart.offer
			//o.refresh()
			if(o?.product?.attributes?.prebook && o?.prebookPrice){
				userCart.netPayableAmount = userCartMap[userCart.id]['netPayableAmount']
				userCart.grossPayableAmount = userCartMap[userCart.id]['grossPayableAmount']
				Double netPayableAmount = userCart.netPayableAmount
				Double netAmountPayable = netPayableAmount / totalAmount
				Double advAmountPayable = advAmount
				String cat = o.product.attributes['mastercategory']
				//if(cat == 'Mobiles') {
				/*if(payTM) {
                    if (payTM?.advAmountType==DeltaTypeEnum.PERCENTAGE) {
                        advAmountPayable = (netPayableAmount * advAmount) / 100
                    } else {
                        //advAmountPayable = (netAmountPayable * advAmount)
                        advAmountPayable = advAmount
                    }
                }*/
				/*}else {
                    advAmountPayable = 0
                }*/
				grossTotal += userCart.grossPayableAmount
				if(userCart.grossPayableAmount > userCart.netPayableAmount) {
					additionalDiscount += userCart.grossPayableAmount - userCart.netPayableAmount
				}else {
					additionalSurcharge += userCart.netPayableAmount - userCart.grossPayableAmount
				}
				advAmountPayable = Math.min(advAmountPayable, userCart.netPayableAmount)
				userCart.advAmountPayable = advAmountPayable.round(2)
				userCart.isAdvanceAmountApplicable = advAmountPayable > 0
				advanceAmount += advAmountPayable.round(2)
				//userCart.save(flush:true, deepValidate:false)
				saveCart(userCart,userCartMap,advAmountPayable);
			}
		}
		//advanceAmount = Math.min(advanceAmount?:0, advAmount);
		advanceAmount = advanceAmount.round(2);
		rstsMap['advanceAmount'] =advanceAmount
		rstsMap['additionalDiscount'] =additionalDiscount
		rstsMap['additionalSurcharge'] =additionalSurcharge
		rstsMap['grossTotal'] = grossTotal
		rstsMap
	}

	@Retryable(maxAttempts = 5,backoff = @Backoff(4000L))
	def saveCart(def userCart,userCartMap,def advAmountPayable){

		if(userCart){
			userCart.refresh();
			userCart.netPayableAmount = userCartMap[userCart.id]['netPayableAmount']
			userCart.grossPayableAmount = userCartMap[userCart.id]['grossPayableAmount']
			userCart.advAmountPayable = advAmountPayable.round(2)
			userCart.isAdvanceAmountApplicable = advAmountPayable > 0
			userCart.save(flush:true, deepValidate:false)
		}
	}

	def calculateComboDiscount(MerchantProductOffer offer,SuggestedCombo combo){
		def discountValue = 0
		def offerPrice = 0
		combo.offers.each{ off ->
			if(offer.id.toString().equals(off.id.toString())){
				discountValue = off.comboDiscountValue ? off.comboDiscountValue : 0
				offerPrice = off.offerPrice;
			}
		}
		if(discountValue == 0){
			discountValue = combo.comboDiscount*offerPrice/combo.totalPrice;
		}else if(combo.discountType.toString().equalsIgnoreCase(DeltaTypeEnum.PERCENTAGE.toString())){
			discountValue = (discountValue/100)*combo.comboDiscount;
		}
		return discountValue.round(2);
	}

	def isPayTMApplicable(Double amount, String webSite) {
		String transactionAmount =servletContext.configuration."${webSite}".'paytm_transaction_amount'
		String transactionCount =servletContext.configuration."${webSite}".'paytm_transaction_count'
		String dailyTransactionAmount =servletContext.configuration."${webSite}".'paytm_daily_transaction_amount'
		Double allowedTxnAmount = transactionAmount ? Double.parseDouble(transactionAmount.toString()) : 0
		Boolean retVal = false
		Map map = [:]
		if(amount <= allowedTxnAmount) {
			Double allowedTxnCount = transactionCount ? Double.parseDouble(transactionCount.toString()) : 0
			if(allowedTxnCount) {
				Double allowedDailyTxnAmount =  dailyTransactionAmount ? Double.parseDouble(dailyTransactionAmount.toString()) : 0
				if(allowedDailyTxnAmount) {
					Date today = new Date()
					Calendar cal = Calendar.getInstance()
					cal.setTime(today)
					Date date = lakshyaUtilsService.getStartDate(cal)
					def txnCount = 1
					Double txnAmount = amount
					PayTMLimit limit = PayTMLimit.findByValidFromDate(date)
					if(limit) {
						txnCount += limit.transactionCount
						txnAmount += limit.dailyTransactionAmountUsed
					}
					if(txnCount <= allowedTxnCount && txnAmount <= allowedDailyTxnAmount) {
						retVal =  true
					}
				}
			}
		}
		return retVal
	}

	def getAddress(def usr, def selectedAddressId, wst){
		def addresses = UserAddressExtension.findAllByUserAndWebSite(usr, WebSite.get(wst), [sort: "selectedAddress",order: "desc"])
		def address = []
		def addressmap = [:]
		def selectedaddressmap = [:]
		addresses.each{ ad ->
			addressmap = [:]
			addressmap.id = ad.id
			addressmap.salutation = ad.salutation
			addressmap.firstName = ad.firstName
			addressmap.lastName = ad.lastName
			addressmap.company = ad.gstin ? ad.company : usr?.company
			addressmap.addressLine1 = ad.addressLine1
			addressmap.addressLine2 = ad.addressLine2
			addressmap.state = ad.state
			addressmap.city = ad.city
			addressmap.area = ad.area
			addressmap.pinCode = ad.pinCode
			addressmap.phone = ad.phone
			addressmap.gstin = ad.gstin
			addressmap.defaultAddress = ad.defaultAddress
			addressmap.selectedAddress = ad.selectedAddress
			addressmap.landmark = ad.landmark
			addressmap.latitude  = ad.latitude
			addressmap.longitude = ad.longitude

			if(ad.selectedAddress && selectedAddressId){
				ad.selectedAddress = false
				ad.save(flush:true, deepValidate:false)
			}
			if(ad.selectedAddress){
				selectedaddressmap = addressmap
			}
			if(selectedAddressId && selectedAddressId.equals(ad.id?.toString())){
				ad.selectedAddress = true
				ad.save(flush:true, deepValidate:false)
				selectedaddressmap = addressmap
			}
			addressmap.isSelectedAddress = ad.selectedAddress?ad.selectedAddress:false
			if(!ad.selectedAddress){
				address << addressmap
			}
		}
		def listAddress = []
		if(!selectedaddressmap.isEmpty()){
			listAddress << selectedaddressmap
		}
		address.each { ad -> listAddress << ad }

		if(!selectedAddressId){
			address = []
			def dlistAddress = []
			listAddress.each{ addr ->
				if(addr.defaultAddress){
					addr.isSelectedAddress = true
					dlistAddress << addr
				}else{
					addr.isSelectedAddress = false
					address << addr
				}
			}
			address.each { ad -> dlistAddress << ad }
			return dlistAddress

		}

		return listAddress
	}

	def setAdditionalDiscountSurcharge(def responseMap, def usr, def wst, def cartId){
		def grandTotal = responseMap.paymentMap.grandTotal
		def paymentMethodType = responseMap.paymentMap.paymentMethodType
		def paymentInfo = lakshyaOrderService.getAdditionalDiscountSurchargeInfo(grandTotal, paymentMethodType, usr, cartId, wst)
		def additionalType
		def additonalDiscount
		def additionalSurcharge
		if(paymentInfo){
			paymentInfo = paymentInfo.tokenize(':')
			DecimalFormat df2 = new DecimalFormat(".")

			additionalType = paymentInfo[1].toString()
			if("Surcharge".equals(additionalType)){
				String srchg = paymentInfo[0]?.toString()
				additionalSurcharge = new Double(srchg)
				responseMap.paymentMap.additionalSurcharge = additionalSurcharge
				responseMap.paymentMap.grandTotal = grandTotal + additionalSurcharge
			}
			if("Discount".equals(additionalType)){
				String discnt = paymentInfo[0]?.toString()
				additonalDiscount = new Double(discnt)
				responseMap.paymentMap.additonalDiscount = additonalDiscount
				responseMap.paymentMap.grandTotal = grandTotal - additonalDiscount
			}
			responseMap.paymentMap.grandTotal = Utils.setScale(responseMap.paymentMap.grandTotal)
			//paymentMap["summary"] = summary
		}
		return responseMap
	}

	def updateFirmName(User user, String firmName, String gstin){
		def sale = Sale.createCriteria().list(){
			eq('user', user)
			not{'in'('status', (['PENDING', 'CANCELLED']))}
		}
		if(!sale){
			def userAddresses = UserAddress.createCriteria().list(){
				eq('user', user)
				ne('company', firmName)
			}
			userAddresses.each{UserAddress address->
				address.company = firmName
				address.gstin = gstin
				address.save flush:true
			}
			if(!user.company.toString().equals(firmName)){
				user.company = firmName
				user.gstin = gstin
				user.save flush:true
			}
		}
	}

