toolUseResult.originalFile:
const EventBus = new Vue();
let selectedWarranty = null;
let selectedWms = null;

function showAlertMessage(state, message) {
    window.scrollTo(0, 0)
    EventBus.$emit('show-alert-message', {
        status: state,
        message: message
    });
}

function getTimeLeft(deadline) {
    const timeLeft = new Date(deadline) - new Date();
    let hours, minutes, seconds;
    // 1- Convert to seconds:
    seconds = Math.floor(timeLeft / 1000);

    // 2- Extract hours:
    hours = Math.floor( seconds / 3600 ); // 3,600 seconds in 1 hour
    seconds = seconds % 3600; // seconds remaining after extracting hours

    // 3- Extract minutes:
    minutes = Math.floor( seconds / 60 ); // 60 seconds in 1 minute

    // 4- Keep only seconds not extracted to minutes:
    seconds = seconds % 60;

    //seconds < 10 ? seconds = `0${seconds}`: seconds = `${seconds}`
    minutes < 10 ? minutes = `0${minutes}`: minutes = `${minutes}`
    hours < 10 ? hours = `0${hours}`: hours = `${hours}`

    return `${hours} hours and ${minutes} mins`
}

function showSpinner(status) {
    status ? $('body').addClass('item-loader') : $('body').removeClass('item-loader');
}

/* check status and return parsed json on success */
function checkStatus(response) {
    if (response.ok) {
        if (response.redirected) { // 302
            location.href = response.url;

            throw new Error('Authorization Failed');
        } else {
            return response.json();
        }
    } else {
        const error = new Error(response.statusText);
        error.status = response.status;
        error.response = response;
        throw error;
    }
}

function fetchRequestErrorHandler(error) {
    console.log('Request failed.');
    showSpinner(false)
}

