                            <div class="row m-b-10 wms p-10">
                                <div class="col-xs-12 wms">
                                    <select class="form-control" name="wmsCode" v-model="selectedWms" @change="selectWms(selectedWms)">
                                        <option :value="null">Choose a warehouse</option>
                                        <option v-for="wms in wmsList" :key="wms.code" :value="wms.code" name="wmsCode">
                                            {{ wms.name }}
                                        </option>
                                    </select>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                `,
        props: ['page'],
        data: function () {
            return {
                wmsList: [],
                selectedWms: null
            };
        },
        methods: {
            selectWms(wmsCode) {
                if (!wmsCode) {
                    this.selectedWms = null;
                    selectedWms = null;
                    // document.getElementById('wmsCode').value = "";
                    showAlertMessage(false, 'WMS removed');
                    //return;
                }
                this.selectedWms = wmsCode;
                selectedWms = wmsCode;
                document.getElementById('wmsCode').value = wmsCode;

                showSpinner(true);
                const cartId = this.$props.page === 'cart' ? '' : (window.shippingPage ? window.shippingPage.cartId : '');
                const url = `/cart/selectWms?cartId=`+cartId+"&wmsCode="+wmsCode;

                fetch(url, {
                    method: 'GET',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    /*body: JSON.stringify({
                        cartId: cartId,
                        wms: wmsCode
                    }),*/
                })
                    .then(checkStatus)
                    .then((response) => {
                        showSpinner(false);
                        if (response.statusCode === '200 OK' || response.status === true) {
                            showAlertMessage(true, response.message || 'WMS updated successfully');
                            EventBus.$emit('refreshOrderSummary', { summary: response });
                            EventBus.$emit('refreshPromos');
                        } else {
                            this.selectedWms = null;
                            selectedWms = null;
                            showAlertMessage(false, response.message || 'Failed to update WMS');
                        }
                    }).catch((error) => {
                    this.selectedWms = null;
                    selectedWms = null;
                    fetchRequestErrorHandler(error);
                });
            },
            loadWmsListFromAPI(wmsList) {
                if (wmsList && Array.isArray(wmsList)) {
                    this.wmsList = wmsList;
                } else if (wmsList) {
                    // If wmsList is an object with a wmsList array
                    this.wmsList = wmsList.wmsList || [];
                } else {
                    this.wmsList = [];
                }
            }
        },
        mounted() {
            // Load service plans from global shippingPage object if available
            if (window.shippingPage && window.shippingPage.wmsList) {
                this.loadWmsListFromAPI(window.shippingPage.wmsList);
            }

            // Restore warranty selection when reloading step
            if (selectedWms) {
                this.selectedWms = selectedWms;
            }

            // Listen for service plans updates from selectAddress API
            EventBus.$on('refreshWmsList', (data) => {
                if (data && data.wmsList) {
                    this.loadWmsListFromAPI(data.wmsList);
                }
                // Restore selection if it exists
                if (selectedWms) {
                    this.selectedWms = selectedWms;
                }
            });
        },
        beforeDestroy() {
            EventBus.$off('refreshWmsList');
        }
    });

    // Register the constructor with id
    Vue.component('available-coupons', availabaleCouponsTemplate);
    Vue.component('warranty-template', warrantyTemplate);
    Vue.component('confirmation-dialog', confirmationTemplate);
    Vue.component('bulk-quantuty-modal', bulkModelTemplate);
    Vue.component('payment-summary', paymentSummaryTemplate);
    Vue.component('cart-items-list', cartitemsTemplate);
    Vue.component('wms-template', wmsTemplate);
})();

