                this.disableContinue = !!(isNotServiceable || apiResponse.anyItemOutOfStock)
                this.loaded = true;
                this.paymentSummaryRefreshCounter++;
                this.removeLoader();
            },
            onWarrantyPlansLoaded: function(hasPlans) { // ADDED
                // this.hasWarrantyPlans = hasPlans;
            },
            refreshPaymentData: function () {
                this.getPaymentSummary();
            },
            removeLoader: function () {
                $('body').removeClass('item-loader')
            },
            showLoader: function () {
                $('body').addClass('item-loader')
            }
        },
        mounted() {
            this.getPaymentSummary();
            EventBus.$on('refreshPaymentSummary', () => {
                this.gotPaymentSummary()
            });
        },
        beforeDestroy() {
            EventBus.$off('refreshPaymentSummary');
        }
    });

    shippingPage.refreshOrderSummary = function (response) {
        EventBus.$emit('refreshOrderSummary', {summary: response});
    };

    shippingPage.showAlertMessage = function (messageObj) {
        EventBus.$emit('show-alert-message', {
            status: messageObj.status,
            message: messageObj.message
        });
    };

    //NETBANKING CREDIT_DEBIT CASHONDELIVERY CHEQUE POSTDATEDCHEQUE CREDIT14 CREDIT28 NEFTRTGS
    shippingPage.updatePaymentSummary = function (mode, paymentMap, grandTotal, walletBalance = 0, creditBalance = 0) {
        apiResponse.paymentSummary.walletApplied = walletBalance == 0 ? undefined : walletBalance;
        apiResponse.paymentSummary.creditApplied = creditBalance == 0 ? undefined : creditBalance;
        const totalApplied= Number(walletBalance) + Number(creditBalance);
        if ((Math.round(walletBalance) == Math.round(grandTotal)) || mode == '') { //walletApplied
            apiResponse.paymentSummary.paymentDiscount = undefined;
            apiResponse.paymentSummary.paymentSurchrge = undefined;


            apiResponse.paymentSummary.grandTotal = totalApplied == 0 ? grandTotal : Math.round(grandTotal - totalApplied);

        } else {
            let discount = paymentMap[mode].discount,
                surcharge = paymentMap[mode].surcharge;

            let total = grandTotal - totalApplied;
            discount =discount > total ? total : discount

            apiResponse.paymentSummary.paymentDiscount = discount;
            apiResponse.paymentSummary.paymentSurchrge = surcharge;



            if (discount) {
                total = total - discount;
            } else if (surcharge) {
                total = total + surcharge;
            }

            apiResponse.paymentSummary.grandTotal = Math.round(total);
        }

        EventBus.$emit('refreshOrderSummary', {
            summary: apiResponse
        });
    };
    $(function() {
        window.setTimeout(() => {
            showMinimumOrderValeMsg(apiResponse.paymentSummary.grandTotal);
        }, 3000);
        //showMinimumOrderValeMsg();
    })
})();

