                // tomorrow.setDate(today.getDate() + 2); // Add 2 days
                for (let index = 0; index < cartItems?.length; ++index) {

                    const cartItem = cartItems[index];
                    // const date = new Date(cartItems[index].buyerExpectedDeliveryDate || tomorrow)
                    const dateValue = cartItems[index].buyerExpectedDeliveryDate;
                    const date = dateValue ? new Date(dateValue) : null;
                    if(date) {
                        const year = date.getFullYear();
                        const month = String(date.getMonth() + 1).padStart(2, '0'); // Add leading zero
                        const day = String(date.getDate()).padStart(2, '0'); // Add leading zero
                        // return `${year}-${month}-${day}`;

                        cartItems[index].buyerExpectedDeliveryDate = `${year}-${month}-${day}`;
                    }
                    else{
                        cartItems[index].buyerExpectedDeliveryDate = ''
                    }
                    if (cartItem.offerUpdated && !cartItem.outOfStock) {
                        this.offerUpdated = true;
                        break;
                    }
                }
                this.cartItems = cartItems;

                if (this.cartItems.length !== 0) {
                    EventBus.$emit('refreshPaymentSummary');
                    if (apiResponse.wmsList) {
                        window.shippingPage.wmsList = apiResponse.wmsList;
                        EventBus.$emit('refreshWmsList', {
                            wmsList: window.shippingPage.wmsList
                        });
                    }
                } else {
                    this.removeLoader();
                }
            },
            removeLoader: function () {
                $('body').removeClass('item-loader')
            },
            showTierPricing: function () {
                this.currentModal = $(`#${event.currentTarget.getAttribute('cartid')}`).find('.modal-mask')
                this.currentModal.modal('show')
            },
            showLoader: function () {
                $('body').addClass('item-loader')
            }

        },
        mounted() {
            //this.getOrderSummary();
            EventBus.$on('reloadOrderSummary', () => {
                this.getOrderSummary();
            });
            EventBus.$on('refreshOrderSummary', (order) => {
                apiResponse = order.summary;
                this.gotOrderSummary()
            });
            EventBus.$on('confirmationClosed', () => {
                this.confirmModal = false;
                this.confirmationdata = {}
            });
            EventBus.$on('cartItemRemoved', (order) => {
                cartItemRemoved(apiResponse.cartItems.filter(cartItem => {return cartItem.id == order.removedCartId})[0], pageName);
                apiResponse = order.summary;
                this.gotOrderSummary();
            });
        },
        beforeDestroy() {
            EventBus.$off('reloadOrderSummary');
            EventBus.$off('refreshOrderSummary');
            EventBus.$off('confirmationClosed');
            EventBus.$off('cartItemRemoved');
        }
    });

    const paymentData = {
        //page
        loaded: false,
        isAnyItemOutOfStock: false,
        isCartNotEmpty: false,
        showAvailableCoupons: true,
        confirmModalPayment: false,
        confirmationDataPayment: {},

        screenWidth: window.screen.width,
        // payment summary section
        paymentSummary: [],
        paymentSummaryRefreshCounter: 0, //refresh payement summary
        disableContinue: false,
    };

    const updatePlaceOrderButtons = (disabled) => {
        $("#isplaceOrderAllowed").val(!disabled);
        const buttons = [
            "#payByNet", "#payByCard", "#payByUpi", "#payByRupifi",
            "#payByCod", "#payByCheque", "#payByChequePdc", "#payByCredit14",
            "#payByCredit28", "#payByNeftRtgs", "#payByPaylater", "#payByCodCard"
        ];
        buttons.forEach(id => {
            const el = $(id);
            if (disabled) {
                el.addClass("disable-content");
            } else {
                el.removeClass("disable-content");
            }
        });
    };

    const paymentSummary = new Vue({
        template: '#paymentSummaryItems',
        data: paymentData,
        watch: {
            disableContinue: function (newVal) {
                updatePlaceOrderButtons(newVal);
            }
        },
        methods: {
            confirmRemove: function () {
                this.confirmationDataPayment.cartId = arguments[0].currentTarget.dataset.cartId;
                this.confirmationDataPayment.couponId = arguments[0].currentTarget.dataset.couponId;
                this.confirmModalPayment = true;
            },
            getCouponValue: function (value) {
                return parseInt(value) === value ? value : value.toFixed(2);
            },
            getPaymentSummary: function () {
                this.showLoader()
                this.gotPaymentSummary()
            },
            gotPaymentSummary: function () {
                if (shippingPage.userOnPayment && shippingPage.isCouponUpdated) {
                    shippingPage.isCouponUpdated = false;
                    loadPaymentMethods(null)
                }
                this.isCartNotEmpty = apiResponse.cartItems.length > 0;
                this.paymentSummary = apiResponse.paymentSummary;
                this.isAnyItemOutOfStock = apiResponse.anyItemOutOfStock;
                if(apiResponse.cartItems.length > 0) {
                    this.showAvailableCoupons = apiResponse.cartItems[0].preOrderId ? false : true;
                }
                const isNotServiceable = !!(apiResponse.notServicableCartList && apiResponse.notServicableCartList.length > 0);
                this.disableContinue = !!(isNotServiceable || apiResponse.anyItemOutOfStock)
                this.loaded = true;
                this.paymentSummaryRefreshCounter++;
                this.removeLoader();
            },
            onWarrantyPlansLoaded: function(hasPlans) { // ADDED
                // this.hasWarrantyPlans = hasPlans;
            },
            refreshPaymentData: function () {
                this.getPaymentSummary();
            },
            removeLoader: function () {
                $('body').removeClass('item-loader')
            },
            showLoader: function () {
                $('body').addClass('item-loader')
            }
        },
        mounted() {
            this.getPaymentSummary();
            EventBus.$on('refreshPaymentSummary', () => {
                this.gotPaymentSummary()
            });
        },
        beforeDestroy() {
            EventBus.$off('refreshPaymentSummary');
        }
    });

    shippingPage.refreshOrderSummary = function (response) {
        EventBus.$emit('refreshOrderSummary', {summary: response});
    };

    shippingPage.showAlertMessage = function (messageObj) {
        EventBus.$emit('show-alert-message', {
            status: messageObj.status,
            message: messageObj.message
        });
    };

    //NETBANKING CREDIT_DEBIT CASHONDELIVERY CHEQUE POSTDATEDCHEQUE CREDIT14 CREDIT28 NEFTRTGS
    shippingPage.updatePaymentSummary = function (mode, paymentMap, grandTotal, walletBalance = 0, creditBalance = 0) {
        apiResponse.paymentSummary.walletApplied = walletBalance == 0 ? undefined : walletBalance;
        apiResponse.paymentSummary.creditApplied = creditBalance == 0 ? undefined : creditBalance;
        const totalApplied= Number(walletBalance) + Number(creditBalance);
        if ((Math.round(walletBalance) == Math.round(grandTotal)) || mode == '') { //walletApplied
            apiResponse.paymentSummary.paymentDiscount = undefined;
            apiResponse.paymentSummary.paymentSurchrge = undefined;


            apiResponse.paymentSummary.grandTotal = totalApplied == 0 ? grandTotal : Math.round(grandTotal - totalApplied);

        } else {
            let discount = paymentMap[mode].discount,
                surcharge = paymentMap[mode].surcharge;

            let total = grandTotal - totalApplied;
            discount =discount > total ? total : discount

            apiResponse.paymentSummary.paymentDiscount = discount;
            apiResponse.paymentSummary.paymentSurchrge = surcharge;



            if (discount) {
                total = total - discount;
            } else if (surcharge) {
                total = total + surcharge;
            }

            apiResponse.paymentSummary.grandTotal = Math.round(total);
        }

        EventBus.$emit('refreshOrderSummary', {
            summary: apiResponse
        });
    };
    $(function() {
        window.setTimeout(() => {
            showMinimumOrderValeMsg(apiResponse.paymentSummary.grandTotal);
        }, 3000);
        //showMinimumOrderValeMsg();
    })
})();

